function weddingSceneNarration(scene,style){const chinese={sedan:'锣鼓渐歇，花轿停在喜堂门前。红帘轻动，良辰已至。',silk:'红绸轻牵，喜堂灯火映着两人并肩而行。',bow:'喜烛映红堂前，这一拜郑重落下。',couple:'四周喧声渐远，两人隔着红绸相对而拜。',toast:'喜烛摇红，两只酒杯在彼此面前轻轻相碰。',veil:'夜色渐深，喜秤缓缓挑起红盖头的一角。'},modern={welcome:'玻璃穹顶映着晚霞，花瓣沿长廊轻轻落下。',aisle:'乐声渐近，两人牵着手走过铺满花瓣的长廊。',vow:'誓词在指间展开，四周渐渐安静下来。',ring:'戒指缓缓戴过指尖，停在左手无名指上。',kiss:'婚戒在指间映着光，他托住你的手，在手背落下郑重的一吻。',embrace:'掌声与祝福一同响起，他在花雨里拥住你。'};return(style==='chinese'?chinese:modern)[scene]||'这一刻安静下来，只剩彼此近在眼前。';}
