function weddingState(){S.weddingModern=S.weddingModern&&typeof S.weddingModern==='object'?S.weddingModern:{};S.weddingModern.records=Array.isArray(S.weddingModern.records)?S.weddingModern.records:[];S.weddingModern.invitation=S.weddingModern.invitation&&typeof S.weddingModern.invitation==='object'?S.weddingModern.invitation:{};const inv=S.weddingModern.invitation;inv.autoSentDays=inv.autoSentDays&&typeof inv.autoSentDays==='object'&&!Array.isArray(inv.autoSentDays)?inv.autoSentDays:{};if(inv.autoSentAt&&!inv.autoSentDays[WEDDING_RELEASE_DAY])inv.autoSentDays[WEDDING_RELEASE_DAY]=inv.autoSentAt;const cid=S.couple&&S.couple.cid||'';if(cid&&!inv.autoSentDays[WEDDING_RELEASE_DAY]){const old=(msgs(cid)||[]).find(m=>m&&m.source==='auto'&&(m.type==='weddinginvite'||m._weddingInviteIntro));if(old){inv.autoSentDays[WEDDING_RELEASE_DAY]=+old.time||Date.now();inv.autoSentAt=inv.autoSentAt||inv.autoSentDays[WEDDING_RELEASE_DAY];}}S.weddingModern.prepared=S.weddingModern.prepared&&typeof S.weddingModern.prepared==='object'?S.weddingModern.prepared:{};return S.weddingModern;}
