function weddingOfflineStyleHTML(c,style){style=weddingStyleKey(style);const label=style==='chinese'?'中式':'现代',ready=weddingLatestReadyInvite(c,style),pending=msgs(c.id).find(x=>x&&x.type==='weddinginvite'&&(x.phase==='preparing'||x.phase==='scheduled')&&(x.style||'modern')===style&&!x.cancelledAt),red=style==='chinese'?' wedding-offline-entry-chinese':'';if(ready)return '<section class="wedding-offline-entry'+red+'"><div class="wedding-offline-copy"><small>'+(style==='chinese'?'CHINESE CEREMONY':'PRIVATE CEREMONY')+'</small><b>'+label+'婚礼仪式</b><span>和 '+esc(weddingRoleName(c))+' 的整场婚礼已经准备完成</span></div><div class="wedding-offline-actions wedding-offline-actions-ready"><button type="button" class="primary" onclick="event.stopPropagation();closeModal();weddingOpenReadyInvite(\''+c.id+'\',\''+ready.id+'\')">进入婚礼</button><button type="button" onclick="event.stopPropagation();closeModal();weddingStartSimulation(\''+c.id+'\',\''+ready.id+'\',\''+style+'\')">模拟一次 · 不保存</button><button type="button" onclick="event.stopPropagation();weddingOpenSceneRegenerator(\''+c.id+'\',\''+ready.id+'\')">单独重做某一章</button><button type="button" onclick="event.stopPropagation();closeModal();weddingRegenerate(\''+c.id+'\',\''+style+'\')">重新生成'+label+'婚礼</button></div></section>';if(pending){const scheduled=pending.phase==='scheduled',status=scheduled?'<span data-wedding-countdown="'+pending.eventAt+'">'+esc(weddingCountdownText(pending.eventAt))+'</span>':'<span data-wedding-preparing="'+pending.id+'">'+esc(weddingPrepTimeText(pending))+'</span>';return '<section class="wedding-offline-entry'+red+'"><div class="wedding-offline-copy"><small>'+(style==='chinese'?'CHINESE CEREMONY':'PRIVATE CEREMONY')+'</small><b>'+label+(scheduled?'婚礼开放倒计时':'婚礼后台准备中')+'</b>'+status+(scheduled?'':'<em class="wedding-stay-note">准备期间请不要退出小手机或锁屏</em>')+'</div><button type="button" onclick="event.stopPropagation();toast(\''+(scheduled?'倒计时结束后，他会发来可进入的邀请卡':'整场准备完成后，他会发来可进入的邀请卡')+'\')">等待他发来邀请</button></section>';}return '<section class="wedding-offline-entry'+red+'"><div class="wedding-offline-copy"><small>'+(style==='chinese'?'CHINESE CEREMONY':'PRIVATE CEREMONY')+'</small><b>'+label+'婚礼仪式</b><span>先一次性准备完整台词与六幕画面，完成后由他发来邀请</span></div><button type="button" class="primary" onclick="event.stopPropagation();closeModal();weddingRegenerate(\''+c.id+'\',\''+style+'\')">后台准备'+label+'婚礼</button></section>';}
function weddingOfflineEntryHTML(){const c=weddingInvitationRole();if(!c)return '<section class="wedding-offline-entry wedding-offline-entry-disabled"><div class="wedding-offline-copy"><small>PRIVATE CEREMONY</small><b>婚礼仪式</b><span>婚礼只对情侣空间绑定的角色开放</span></div><button type="button" onclick="event.stopPropagation();toast(\'请先在情侣空间绑定婚礼角色\')">尚未绑定情侣角色</button></section>';const clear=weddingHasStoredData(c)?'<button type="button" class="wedding-clear-all" onclick="event.stopPropagation();weddingClearAll(\''+c.id+'\')">清空所有婚礼记忆、婚书与夫妻关系</button>':'';return '<div class="wedding-offline-styles">'+weddingOfflineStyleHTML(c,'modern')+weddingOfflineStyleHTML(c,'chinese')+clear+'</div>';}

