function weddingCountdownText(at){let ms=Math.max(0,(+at||Date.now())-Date.now()),days=Math.floor(ms/86400000);ms-=days*86400000;const h=Math.floor(ms/3600000),min=Math.floor(ms%3600000/60000),sec=Math.floor(ms%60000/1000),pad=n=>String(n).padStart(2,'0');return '距离婚礼还有 '+(days?days+'天 ':'')+pad(h)+':'+pad(min)+':'+pad(sec);}
function weddingPrepRemainingMs(m){const p=m&&m.preparation||{},done=Math.max(0,+p.done||0),total=Math.max(1,+p.total||WEDDING_PREP_TOTAL),elapsed=Math.max(0,Date.now()-(+p.startedAt||Date.now()));if(done>=total)return m&&m.preparedAt?Math.max(0,(+m.eventAt||Date.now())-Date.now()):0;if(done<=0)return Math.max(60000,+p.estimateMs||WEDDING_PREP_DEFAULT_MS);const average=Math.max(25000,elapsed/done);return Math.max(15000,average*(total-done));}
