async function weddingStoreCurrentScene(c,scene,formalwear,style,src,verify,opt){style=weddingStyleKey(style);opt=opt||{};const key=weddingSceneKey(c,scene,formalwear,W.generationId,style),storedVerify=Object.assign({},verify||{pass:true,reason:'已生成'},opt.delivered?{delivered:true}:{});W.sceneImages[scene]=src;W.sceneVerify[scene]=storedVerify;delete W.sceneFailures[scene];delete W.sceneCandidates[scene];if(typeof imgPut==='function')await imgPut(key,{src,verified:storedVerify,createdAt:Date.now(),retried:!!opt.retried,returnedCandidate:!!opt.delivered,referenceScene:opt.referenceScene||''});return src;}
weddingRetryFailedScene=async function(c,scene,formalwear,style){style=weddingStyleKey(style);const existing=W.sceneCandidates&&W.sceneCandidates[scene];if(existing&&existing.src)return weddingStoreCurrentScene(c,scene,formalwear,style,existing.src,existing.verify,{delivered:true,referenceScene:existing.referenceScene||''});let lastError=null;for(let attempt=1;attempt<=2;attempt++){const reference=weddingIdentityReference(scene,style);try{const src=await weddingGenerateScene(c,scene,formalwear,{reference,reason:'第 '+attempt+' 次重新请求。本次只发起一张生图；必须沿用第一幕身份，只修正本章动作和镜头。',style});return weddingStoreCurrentScene(c,scene,formalwear,style,src,W.sceneVerify[scene],{retried:true,referenceScene:reference&&reference.scene||''});}catch(e){lastError=e;if(e&&e.weddingCandidate)return weddingStoreCurrentScene(c,scene,formalwear,style,e.weddingCandidate,e.weddingCandidateVerify,{delivered:true,retried:true,referenceScene:reference&&reference.scene||''});}}W.sceneImages[scene]=weddingScenes(style)[scene];W.sceneVerify[scene]={pass:false,reason:String(lastError&&lastError.message||lastError||'两次请求均未返回图片').slice(0,160)};return W.sceneImages[scene];};
function weddingLatestPreparedEntry(c,style){
  style=weddingStyleKey(style);
  return Object.entries(weddingState().prepared)
    .filter(([,prepared])=>prepared&&prepared.cid===c.id&&weddingStyleKey(prepared.style)===style)
    .map(([id,prepared])=>({id,prepared}))
    .sort((a,b)=>(+b.prepared.updatedAt||+b.prepared.preparedAt||0)-(+a.prepared.updatedAt||+a.prepared.preparedAt||0))[0]||null;
}
function weddingResolvePreparedInvite(c,m){
  const st=weddingState();
  if(m&&m.preparedId&&st.prepared[m.preparedId])return{id:m.preparedId,prepared:st.prepared[m.preparedId],exact:true};
  if(m&&m.id&&st.prepared[m.id])return{id:m.id,prepared:st.prepared[m.id],exact:true};
  return c?weddingLatestPreparedEntry(c,m&&m.style||'modern'):null;
}
function weddingPreparedReadyAt(ref,m){
  const prepared=ref&&ref.prepared,at=+prepared?.preparedAt||+m?.preparedAt||Date.now();
  return at+WEDDING_READY_DELAY_MS;
}
async function weddingFinalizeInvitation(c,m){const key='finalize_'+m.id;if(weddingInviteJobs[key]||m.readySentAt)return;const ref=weddingResolvePreparedInvite(c,m);if(!ref)return;weddingInviteJobs[key]=true;try{const readyAt=weddingPreparedReadyAt(ref,m);m.preparedId=ref.id;m.preparedAt=m.preparedAt||ref.prepared.preparedAt;m.eventAt=readyAt;m.eventDate=weddingLocalDay(readyAt);if(Date.now()<readyAt){m.phase='scheduled';save();weddingRefreshInviteChat(c.id);return;}const style=weddingStyleKey(ref.prepared.style||m.style),text=weddingArrivalLine(c,style,ref.prepared.script);m.style=style;m.phase='scheduled';save();if(m.cancelledAt)return;for(const old of msgs(c.id)){if(old&&old!==m&&old.type==='weddinginvite'&&old.phase==='ready'&&(old.style||'modern')===style&&!old.supersededAt)old.supersededAt=Date.now();}m.readySentAt=Date.now();if(m.source==='auto'){m.phase='ready';m.preparedId=ref.id;save();weddingRefreshInviteChat(c.id);return m;}const line={role:'assistant',type:'text',content:text,id:uid(),time:Date.now(),_weddingReady:ref.id,_weddingStyle:style},ready=weddingEnsureInviteFormat({role:'assistant',type:'weddinginvite',phase:'ready',schema:2,style,id:uid(),time:Date.now()+1,source:m.source,eventDate:m.eventDate,eventAt:readyAt,calendarEventId:m.calendarEventId||'',preparedId:ref.id});msgs(c.id).push(line,ready);save();try{notifyIncoming(c,line);setTimeout(()=>notifyIncoming(c,ready),450);}catch(_){}weddingRefreshInviteChat(c.id);return ready;}finally{delete weddingInviteJobs[key];}}
async function weddingPrepareInvitation(c,m){if(!weddingEligibleRole(c)||!m)return;const key='prepare_'+m.id;if(weddingInviteJobs[key]||m.readySentAt)return;weddingInviteJobs[key]=true;m.style=weddingStyleKey(m.style);const style=m.style,order=weddingSceneOrder(style),scenes=weddingScenes(style),contracts=weddingContracts(style);m.phase='preparing';m.generationId=m.generationId||('wedgen_'+Date.now()+'_'+weddingHash(m.id));weddingPrepUpdate(c,m,0,'正在生成人设专属台词');try{let script,generated=true;try{script=style==='chinese'?await weddingGenerateChinese(c):await weddingGenerate(c);}catch(_){script=style==='chinese'?weddingChineseFallback(c):weddingFallback(c);generated=false;}if(m.cancelledAt)return;weddingPrepUpdate(c,m,1,'台词已完成，正在准备全部画面');W.generationId=m.generationId;W.sceneImages={};W.sceneJobs={};W.sceneVerify={};W.sceneFailures={};W.sceneCandidates={};const sceneKeys={};for(let i=0;i<order.length;i++){if(m.cancelledAt)return;const scene=order[i];await weddingPrepareScene(c,scene,script.formalwear,true,style);if(W.sceneFailures[scene]){const reference=weddingIdentityReference(scene,style),returned=W.sceneCandidates&&W.sceneCandidates[scene];weddingPrepUpdate(c,m,i+1,returned?'第 '+(i+1)+' 幕图片已返回，正在保存复核结果':'第 '+(i+1)+' 幕没有收到图片，正在参考'+(reference?'第一幕 '+contracts[reference.scene].title:'角色身份锚点')+'重试');await weddingRetryFailedScene(c,scene,script.formalwear,style);delete W.sceneFailures[scene];}weddingPrepUpdate(c,m,i+2,'正在生成并复核第 '+(i+1)+' / '+order.length+' 幕');}if(m.cancelledAt)return;for(const scene of order)sceneKeys[scene]=weddingImageReady()&&W.sceneImages[scene]!==scenes[scene]?weddingSceneKey(c,scene,script.formalwear,m.generationId,style):'';if(m.cancelledAt)return;const st=weddingState(),previewScenes=order.filter(scene=>!weddingImageReady()||W.sceneImages[scene]===scenes[scene]||W.sceneVerify[scene]&&W.sceneVerify[scene].pass===false&&!W.sceneVerify[scene].delivered);for(const id of Object.keys(st.prepared)){const old=st.prepared[id];if(id!==m.id&&old&&old.cid===c.id&&(old.style||'modern')===style)delete st.prepared[id];}st.prepared[m.id]={cid:c.id,style,script,generated,preparedAt:Date.now(),generationId:m.generationId,sceneKeys,previewScenes};m.preparedAt=Date.now();m.preparation.done=WEDDING_PREP_TOTAL;m.preparation.completedAt=m.preparedAt;m.requestedEventAt=+m.eventAt||0;m.eventAt=m.preparedAt+WEDDING_READY_DELAY_MS;m.eventDate=weddingLocalDay(m.eventAt);m.phase='scheduled';save();weddingRefreshInviteChat(c.id);await weddingFinalizeInvitation(c,m);}finally{delete weddingInviteJobs[key];}}
async function weddingLoadPreparedScenes(c,prepared){const style=weddingStyleKey(prepared.style),order=weddingSceneOrder(style),scenes=weddingScenes(style),generationId=prepared.generationId||'first';if(W.generationId===generationId&&order.every(scene=>W.sceneImages[scene]))return true;W.generationId=generationId;W.sceneImages={};W.sceneJobs={};W.sceneVerify={};W.sceneFailures={};W.sceneCandidates={};const previews=new Set(Array.isArray(prepared.previewScenes)?prepared.previewScenes:prepared.usesPreview?order:[]);for(const scene of order){if(previews.has(scene)||!weddingImageReady()){W.sceneImages[scene]=scenes[scene];continue;}const key=prepared.sceneKeys&&prepared.sceneKeys[scene]||weddingSceneKey(c,scene,prepared.script.formalwear,prepared.generationId,style),cached=typeof imgGet==='function'?await imgGet(key):null;if(!cached){W.sceneImages[scene]=scenes[scene];previews.add(scene);continue;}W.sceneImages[scene]=cached.src||cached;W.sceneVerify[scene]=cached.verified||{pass:true,reason:'缓存'};}prepared.previewScenes=Array.from(previews);return true;}
function weddingSceneChapterLabels(style){return weddingStyleKey(style)==='chinese'?['迎亲下轿','牵绣球','拜天地与高堂','夫妻对拜','碰杯敬酒','挑盖头']:['迎接新娘','走过花路','宣读誓言','交换戒指','亲吻手背','礼成拥抱'];}
function weddingSceneRegeneratorHTML(cid,mid,prepared){const style=weddingStyleKey(prepared.style),order=weddingSceneOrder(style),labels=weddingSceneChapterLabels(style),label=style==='chinese'?'中式':'现代';return '<h3>单独重做'+label+'婚礼某一章</h3><div class="hint wedding-scene-regenerate-hint">第 1 张是整场唯一的人物身份基准。重做任意一章时都会参考第 1 张的脸、发型、发色、发冠与礼服；新图通过复核后才覆盖，连续三次失败会保留现在这张。</div><div class="wedding-scene-regenerate-grid">'+order.map((scene,i)=>'<button type="button" onclick="weddingRegenerateScene(\''+cid+'\',\''+mid+'\',\''+scene+'\')"><small>第 '+(i+1)+' 章</small><b>'+esc(labels[i])+'</b></button>').join('')+'</div><button class="btn g wedding-scene-regenerate-close" onclick="closeModal()">取消</button>';}
async function weddingOpenSceneRegenerator(cid,mid){const c=getC(cid),m=weddingEnsureInviteFormat(msgs(cid).find(x=>x&&x.id===mid&&x.type==='weddinginvite'));if(!weddingEligibleRole(c)||!m)return toast('婚礼只能与情侣空间绑定的角色进行');const prepared=weddingState().prepared[m.preparedId];if(!prepared)return toast('这场婚礼的完整画面已经不在本机，请重新生成整场婚礼');if(!weddingImageReady())return toast('当前没有配置可用的生图接口，不能单独重做');openModal('<h3>正在读取六幕婚礼画面</h3><div class="hint">请稍候，不会修改现有画面。</div>');try{await weddingLoadPreparedScenes(c,prepared);openModal(weddingSceneRegeneratorHTML(cid,mid,prepared));}catch(_){closeModal();toast('读取婚礼画面失败，请稍后再试');}}
async function weddingRegenerateScene(cid,mid,scene){const c=getC(cid),m=weddingEnsureInviteFormat(msgs(cid).find(x=>x&&x.id===mid&&x.type==='weddinginvite')),prepared=m&&weddingState().prepared[m.preparedId];if(!weddingEligibleRole(c)||!m||!prepared)return toast('这场婚礼已经失效，请重新打开最新邀请');const style=weddingStyleKey(prepared.style),order=weddingSceneOrder(style),index=order.indexOf(scene),labels=weddingSceneChapterLabels(style);if(index<0)return toast('没有找到这一章');const jobKey='regenerate_scene_'+m.preparedId+'_'+scene;if(weddingInviteJobs[jobKey])return toast('这一章正在重新生成，请稍候');if(!weddingImageReady())return toast('当前没有配置可用的生图接口，不能单独重做');weddingInviteJobs[jobKey]=true;openModal('<h3>正在重做第 '+(index+1)+' 章</h3><div class="hint">'+esc(labels[index])+' · 始终参考第 1 张人物。失败会自动重试两次，原图会一直保留到新图通过复核。</div><div class="wedding-scene-regenerate-wait"><i></i><span>请不要退出小手机或锁屏</span></div>');let originalSrc='',originalVerify=null,lastError=null;try{await weddingLoadPreparedScenes(c,prepared);originalSrc=W.sceneImages[scene]||weddingScenes(style)[scene];originalVerify=W.sceneVerify[scene]||null;const first=order[0],firstSrc=W.sceneImages[first]||weddingScenes(style)[first],reference={scene:first,src:firstSrc};let accepted='',acceptedVerify=null;for(let attempt=1;attempt<=3&&!accepted;attempt++){try{const src=await weddingTimed(weddingGenerateScene(c,scene,prepared.script.formalwear,{style,reference,reason:'这是单独重做第 '+(index+1)+' 章的第 '+attempt+' 次生成。必须严格沿用第一幕人物身份，只修正本章动作和镜头。'}),240000,'第 '+attempt+' 次生成超时');if(W.sceneVerify[scene]&&W.sceneVerify[scene].pass){accepted=src;acceptedVerify=W.sceneVerify[scene];break;}lastError=new Error(W.sceneVerify[scene]&&W.sceneVerify[scene].reason||'动作复核未通过');}catch(e){lastError=e;W.sceneImages[scene]=originalSrc;W.sceneVerify[scene]=originalVerify;}}if(!accepted){W.sceneImages[scene]=originalSrc;W.sceneVerify[scene]=originalVerify;openModal('<h3>原来的第 '+(index+1)+' 章已保留</h3><div class="hint">新图连续三次都没有通过动作与人物一致性复核，没有覆盖你原来满意的画面。'+(lastError?' 最后一次原因：'+esc(String(lastError.weddingReason||lastError.message||lastError).slice(0,100)):'')+'</div><div class="btns"><button class="btn g" onclick="weddingOpenSceneRegenerator(\''+cid+'\',\''+mid+'\')">返回章节选择</button><button class="btn p" onclick="closeModal()">完成</button></div>');return;}const revisionId=(prepared.generationId||'wedding')+'_chapter_'+(index+1)+'_'+Date.now(),cacheKey=weddingSceneKey(c,scene,prepared.script.formalwear,revisionId,style);if(typeof imgPut==='function')await imgPut(cacheKey,{src:accepted,verified:acceptedVerify,createdAt:Date.now(),singleChapter:true,referenceScene:first,referenceRule:'first-scene-only'});W.sceneImages[scene]=accepted;W.sceneVerify[scene]=acceptedVerify;prepared.sceneKeys=prepared.sceneKeys&&typeof prepared.sceneKeys==='object'?prepared.sceneKeys:{};prepared.sceneKeys[scene]=cacheKey;prepared.previewScenes=(Array.isArray(prepared.previewScenes)?prepared.previewScenes:[]).filter(x=>x!==scene);prepared.sceneRevisions=prepared.sceneRevisions&&typeof prepared.sceneRevisions==='object'?prepared.sceneRevisions:{};prepared.sceneRevisions[scene]=(prepared.sceneRevisions[scene]||0)+1;prepared.updatedAt=Date.now();save();openModal('<h3>第 '+(index+1)+' 章已经重做完成</h3><div class="hint">新画面已通过动作复核，并按第 1 张锁定了同一张脸、同一发型和同一套礼服；其他五章没有改变。</div><div class="btns"><button class="btn g" onclick="weddingOpenSceneRegenerator(\''+cid+'\',\''+mid+'\')">继续选择章节</button><button class="btn p" onclick="closeModal();render()">完成</button></div>');}catch(e){W.sceneImages[scene]=originalSrc||W.sceneImages[scene];W.sceneVerify[scene]=originalVerify;openModal('<h3>没有覆盖原图</h3><div class="hint">单章重做暂时失败，原来的画面仍然保留。'+esc(String(e&&e.message||e||'').slice(0,100))+'</div><button class="btn g" onclick="weddingOpenSceneRegenerator(\''+cid+'\',\''+mid+'\')">返回章节选择</button>');}finally{delete weddingInviteJobs[jobKey];}}
weddingSceneRegeneratorHTML=function(cid,mid,prepared){const style=weddingStyleKey(prepared.style),order=weddingSceneOrder(style),labels=weddingSceneChapterLabels(style),label=style==='chinese'?'中式':'现代';return '<h3>单独重做'+label+'婚礼某一章</h3><div class="hint wedding-scene-regenerate-hint">第 1 张是整场唯一的人物身份基准。每点一次章节只发起一张付费生图，不会暗中连发；平台返回的图片会先给你看，再由你决定是否覆盖。</div><div class="wedding-scene-regenerate-grid">'+order.map((scene,i)=>'<button type="button" onclick="weddingRegenerateScene(\''+cid+'\',\''+mid+'\',\''+scene+'\')"><small>第 '+(i+1)+' 章</small><b>'+esc(labels[i])+'</b></button>').join('')+'</div><button class="btn g wedding-scene-regenerate-close" onclick="closeModal()">取消</button>';};
async function weddingCommitSceneRevision(c,m,prepared,scene,src,verify){const style=weddingStyleKey(prepared.style),order=weddingSceneOrder(style),index=order.indexOf(scene),first=order[0],revisionId=(prepared.generationId||'wedding')+'_chapter_'+(index+1)+'_'+Date.now(),cacheKey=weddingSceneKey(c,scene,prepared.script.formalwear,revisionId,style),storedVerify=Object.assign({},verify||{pass:true,reason:'已生成'},{delivered:true});if(typeof imgPut==='function')await imgPut(cacheKey,{src,verified:storedVerify,createdAt:Date.now(),singleChapter:true,referenceScene:first,referenceRule:'first-scene-identity-summary'});W.sceneImages[scene]=src;W.sceneVerify[scene]=storedVerify;prepared.sceneKeys=prepared.sceneKeys&&typeof prepared.sceneKeys==='object'?prepared.sceneKeys:{};prepared.sceneKeys[scene]=cacheKey;prepared.previewScenes=(Array.isArray(prepared.previewScenes)?prepared.previewScenes:[]).filter(x=>x!==scene);prepared.sceneRevisions=prepared.sceneRevisions&&typeof prepared.sceneRevisions==='object'?prepared.sceneRevisions:{};prepared.sceneRevisions[scene]=(prepared.sceneRevisions[scene]||0)+1;prepared.updatedAt=Date.now();save();return true;}
function weddingSceneCandidateModal(token){const item=W.sceneCandidates&&W.sceneCandidates[token];if(!item)return;const reason=String(item.verify&&item.verify.reason||'动作或人物一致性复核没有完全通过').slice(0,120);openModal('<h3>图片已经生成</h3><div class="hint">平台已经返回图片，本次不会再自动扣费重试。内部复核提示：'+esc(reason)+'</div><div style="margin:14px auto;max-width:260px"><img src="'+esc(item.src)+'" alt="本次生成画面" style="display:block;width:100%;max-height:390px;object-fit:contain;border-radius:18px;background:#111"></div><div class="btns"><button class="btn p" onclick="weddingAcceptSceneCandidate(\''+token+'\')">使用这张</button><button class="btn g" onclick="weddingRetrySceneCandidate(\''+token+'\')">再生成一张</button></div><button class="btn g" onclick="weddingDiscardSceneCandidate(\''+token+'\')">保留原图</button>');}
async function weddingAcceptSceneCandidate(token){const item=W.sceneCandidates&&W.sceneCandidates[token];if(!item)return toast('这张候选图已经失效');const c=getC(item.cid),m=c&&weddingEnsureInviteFormat(msgs(c.id).find(x=>x&&x.id===item.mid&&x.type==='weddinginvite')),prepared=m&&weddingState().prepared[m.preparedId];if(!c||!m||!prepared)return toast('这场婚礼已经失效');openModal('<h3>正在保存这张图片</h3><div class="hint">不会再发起生图请求。</div>');try{await weddingCommitSceneRevision(c,m,prepared,item.scene,item.src,item.verify);delete W.sceneCandidates[token];openModal('<h3>这一章已经替换</h3><div class="hint">情侣空间中的高清大图也会读取这张新图，其他章节没有改变。</div><div class="btns"><button class="btn g" onclick="weddingOpenSceneRegenerator(\''+c.id+'\',\''+m.id+'\')">继续选择章节</button><button class="btn p" onclick="closeModal();render()">完成</button></div>');}catch(e){openModal('<h3>图片暂时没有保存成功</h3><div class="hint">没有继续生图，也没有覆盖原图。'+esc(String(e&&e.message||e||'').slice(0,100))+'</div><button class="btn g" onclick="weddingSceneCandidateModal(\''+token+'\')">返回查看图片</button>');}}
function weddingRetrySceneCandidate(token){const item=W.sceneCandidates&&W.sceneCandidates[token];if(!item)return toast('这张候选图已经失效');delete W.sceneCandidates[token];closeModal();setTimeout(()=>weddingRegenerateScene(item.cid,item.mid,item.scene),60);}
function weddingDiscardSceneCandidate(token){const item=W.sceneCandidates&&W.sceneCandidates[token];if(!item)return closeModal();delete W.sceneCandidates[token];weddingOpenSceneRegenerator(item.cid,item.mid);}
weddingRegenerateScene=async function(cid,mid,scene){const c=getC(cid),m=weddingEnsureInviteFormat(msgs(cid).find(x=>x&&x.id===mid&&x.type==='weddinginvite')),prepared=m&&weddingState().prepared[m.preparedId];if(!weddingEligibleRole(c)||!m||!prepared)return toast('这场婚礼已经失效，请重新打开最新邀请');const style=weddingStyleKey(prepared.style),order=weddingSceneOrder(style),index=order.indexOf(scene),labels=weddingSceneChapterLabels(style);if(index<0)return toast('没有找到这一章');const jobKey='regenerate_scene_'+m.preparedId+'_'+scene;if(weddingInviteJobs[jobKey])return toast('这一章正在重新生成，请稍候');if(!weddingImageReady())return toast('当前没有配置可用的生图接口，不能单独重做');weddingInviteJobs[jobKey]=true;openModal('<h3>正在生成第 '+(index+1)+' 章</h3><div class="hint">'+esc(labels[index])+' · 本次只发起一张付费生图，不会自动连发或暗中切换聊天生图。请等待平台返回。</div><div class="wedding-scene-regenerate-wait"><i></i><span>请不要退出小手机或锁屏</span></div>');let originalSrc='',originalVerify=null;try{await weddingLoadPreparedScenes(c,prepared);originalSrc=W.sceneImages[scene]||weddingScenes(style)[scene];originalVerify=W.sceneVerify[scene]||null;const first=order[0],firstSrc=W.sceneImages[first]||weddingScenes(style)[first],reference={scene:first,src:firstSrc};try{const src=await weddingGenerateScene(c,scene,prepared.script.formalwear,{style,reference,reason:'这是单独重做第 '+(index+1)+' 章。本次只发起一张生图，必须严格沿用第一幕人物身份，只修正本章动作和镜头。'});await weddingCommitSceneRevision(c,m,prepared,scene,src,W.sceneVerify[scene]);openModal('<h3>第 '+(index+1)+' 章已经重做完成</h3><div class="hint">平台返回的新图已保存；其他五章没有改变。</div><div class="btns"><button class="btn g" onclick="weddingOpenSceneRegenerator(\''+cid+'\',\''+mid+'\')">继续选择章节</button><button class="btn p" onclick="closeModal();render()">完成</button></div>');}catch(e){W.sceneImages[scene]=originalSrc;W.sceneVerify[scene]=originalVerify;if(e&&e.weddingCandidate){const token='candidate_'+Date.now()+'_'+weddingHash(cid+'|'+mid+'|'+scene+'|'+uid());W.sceneCandidates=W.sceneCandidates||{};W.sceneCandidates[token]={cid,mid,scene,src:e.weddingCandidate,verify:e.weddingCandidateVerify||{pass:false,reason:e.weddingReason||'复核未通过'}};weddingSceneCandidateModal(token);}else openModal('<h3>这次没有收到图片</h3><div class="hint">原图没有被覆盖，也不会自动继续扣费重试。'+esc(String(e&&e.message||e||'').slice(0,110))+'</div><div class="btns"><button class="btn p" onclick="weddingRegenerateScene(\''+cid+'\',\''+mid+'\',\''+scene+'\')">手动再试一次</button><button class="btn g" onclick="weddingOpenSceneRegenerator(\''+cid+'\',\''+mid+'\')">保留原图</button></div>');}}catch(e){W.sceneImages[scene]=originalSrc||W.sceneImages[scene];W.sceneVerify[scene]=originalVerify;openModal('<h3>没有覆盖原图</h3><div class="hint">读取或保存婚礼画面失败，本次没有继续发起请求。'+esc(String(e&&e.message||e||'').slice(0,100))+'</div><button class="btn g" onclick="weddingOpenSceneRegenerator(\''+cid+'\',\''+mid+'\')">返回章节选择</button>');}finally{delete weddingInviteJobs[jobKey];}};
async function weddingEnterPrepared(c,m,prepared,simulation){if(W.busy)return;W.busy=true;const loaded=await weddingLoadPreparedScenes(c,prepared);W.busy=false;if(!loaded){weddingRegenerate(c.id,prepared.style||'modern');return toast('本地画面不完整，已在后台重新准备，不会进入空白婚礼');}m.openedAt=m.openedAt||Date.now();const style=weddingStyleKey(prepared.style),script=style==='chinese'?weddingChineseNormalize(prepared.script||{},c):weddingNormalize(prepared.script||{},c);prepared.script=script;save();W.opening=true;W.session={cid:c.id,style,script,index:0,items:weddingBuildItems(script,!!simulation,style),choices:{},generated:prepared.generated,formalwear:script.formalwear,startedAt:Date.now(),ceremonyAt:m.eventAt,invitationId:m.preparedId||m.id,simulation:!!simulation,brideName:S.me&&S.me.name||'我',groomName:weddingRoleOriginalName(c)};const st=weddingState();if(!simulation){st.lastCid=c.id;save();}weddingShowNameCard(c);}
const weddingEnterPreparedBeforeAlbum=weddingEnterPrepared;
weddingEnterPrepared=async function(c,m,prepared,simulation){const result=await weddingEnterPreparedBeforeAlbum(c,m,prepared,simulation);if(W.session&&W.session.cid===c.id){W.session.preparedId=m.preparedId||m.id;W.session.invitationId=m.preparedId||m.id;}return result;};
async function weddingOpenReadyInvite(cid,mid){const c=getC(cid),m=weddingEnsureInviteFormat(msgs(cid).find(x=>x&&x.id===mid&&x.type==='weddinginvite'));if(!weddingEligibleRole(c)||!m)return toast('婚礼只能与情侣空间绑定的角色进行');if(m.supersededAt)return toast('这张邀请已被新生成的婚礼覆盖，请打开最新卡片');const prepared=weddingState().prepared[m.preparedId];if(!prepared){weddingRegenerate(cid,m.style||'modern');return toast('原婚礼素材不完整，已在后台重新准备');}return weddingEnterPrepared(c,m,prepared,false);}
function weddingInvitationTick(){document.querySelectorAll('[data-wedding-countdown]').forEach(el=>{const at=+el.getAttribute('data-wedding-countdown');el.textContent=Date.now()>=at?'婚礼时间已到':weddingCountdownText(at);});document.querySelectorAll('[data-wedding-preparing]').forEach(el=>{const mid=el.getAttribute('data-wedding-preparing'),c=weddingInvitationRole(),m=c&&msgs(c.id).find(x=>x&&x.id===mid);if(m)el.textContent=weddingPrepTimeText(m);});for(const c of weddingRoles())for(const m of msgs(c.id)){if(!m||m.type!=='weddinginvite'||!m.preparedAt||m.readySentAt||Date.now()<m.eventAt)continue;weddingFinalizeInvitation(c,m);}}
function weddingResumeInvitations(){let repaired=false;for(const c of weddingRoles())for(const raw of msgs(c.id)){if(!raw||raw.type!=='weddinginvite')continue;const before=[raw.schema,raw.phase,raw.id,raw.eventAt,raw.preparedId].join('|'),m=weddingEnsureInviteFormat(raw);if(m.cancelledAt||m.supersededAt)continue;const ref=weddingResolvePreparedInvite(c,m);if(m.phase==='ready'&&!ref){m.phase='preparing';m.readySentAt=0;m.preparedAt=0;m.eventAt=Date.now();repaired=true;}if((m.phase==='preparing'||m.phase==='scheduled')&&!m.readySentAt){if(ref){const readyAt=weddingPreparedReadyAt(ref,m);m.preparedId=ref.id;m.preparedAt=m.preparedAt||ref.prepared.preparedAt;m.eventAt=readyAt;m.eventDate=weddingLocalDay(readyAt);m.phase='scheduled';repaired=true;weddingFinalizeInvitation(c,m);}else weddingPrepareInvitation(c,m);}if(before!==[m.schema,m.phase,m.id,m.eventAt,m.preparedId].join('|'))repaired=true;}if(repaired)save();weddingInvitationTick();}

const weddingFinalizeInvitationBase=weddingFinalizeInvitation;
weddingFinalizeInvitation=async function(c,m){if(!c||!m)return;const ref=weddingResolvePreparedInvite(c,m),preparedId=ref&&ref.id||m.preparedId||m.id,existing=msgs(c.id).find(x=>x&&x.type==='weddinginvite'&&x.phase==='ready'&&x.preparedId===preparedId&&!x.cancelledAt);if(existing){m.preparedId=preparedId;m.readySentAt=m.readySentAt||existing.time||Date.now();return existing;}if(m.readySentAt)m.readySentAt=0;return weddingFinalizeInvitationBase(c,m);};

const weddingOpenSceneRegeneratorInviteOnly=weddingOpenSceneRegenerator;
weddingOpenSceneRegenerator=async function(cid,token){const record=weddingState().records.find(x=>x&&x.id===token&&x.cid===cid);if(!record)return weddingOpenSceneRegeneratorInviteOnly(cid,token);const prepared=weddingPreparedForRecord(record),preparedId=weddingPreparedKey(prepared);if(!prepared||!preparedId)return toast('这场婚礼的完整画面已经不在本机，请重新生成整场婚礼');const carrier=msgs(cid).find(x=>x&&x.type==='weddinginvite'&&(x.preparedId===preparedId||x.id===preparedId));if(!carrier)return toast('这场婚礼缺少生成凭据，请先重新生成整场婚礼');return weddingOpenSceneRegeneratorInviteOnly(cid,carrier.id);};

async function weddingOpenStoredCeremony(cid,recordId){const context=weddingSceneContext(cid,recordId);if(!context||!weddingEligibleRole(context.c))return toast('这场婚礼的完整画面已经不在本机');closeModal();const m=context.m||{id:context.preparedId,preparedId:context.preparedId,eventAt:+context.record.date||Date.now(),style:context.prepared.style,phase:'ready'};return weddingEnterPrepared(context.c,m,context.prepared,false);}

async function weddingRecoverReadyInvite(cid,token,style){
  const c=getC(cid);
  if(!weddingEligibleRole(c))return toast('婚礼只能与情侣空间绑定的角色进行');
  let m=weddingEnsureInviteFormat(msgs(cid).find(x=>x&&x.id===token&&x.type==='weddinginvite'));
  let ref=m?weddingResolvePreparedInvite(c,m):null;
  if(!ref&&token&&weddingState().prepared[token])ref={id:token,prepared:weddingState().prepared[token],exact:true};
  if(!ref)ref=weddingLatestPreparedEntry(c,style||m&&m.style||'modern');
  if(!ref){if(m)return weddingPrepareInvitation(c,m);return toast('这场婚礼的完整画面已经不在本机，请重新生成整场婚礼');}
  const readyAt=weddingPreparedReadyAt(ref,m);
  if(Date.now()<readyAt)return toast(weddingCountdownText(readyAt));
  if(m){m.preparedId=ref.id;m.eventAt=readyAt;try{await weddingFinalizeInvitation(c,m);}catch(_){}const ready=weddingLatestReadyInvite(c,ref.prepared.style);closeModal();if(ready)return weddingOpenReadyInvite(cid,ready.id);}
  closeModal();
  return weddingEnterPrepared(c,{id:ref.id,preparedId:ref.id,eventAt:readyAt,style:ref.prepared.style,phase:'ready'},ref.prepared,false);
}

weddingOfflineStyleHTML=function(c,style){style=weddingStyleKey(style);const label=style==='chinese'?'中式':'现代',ready=weddingLatestReadyInvite(c,style),pending=msgs(c.id).filter(x=>x&&x.type==='weddinginvite'&&(x.phase==='preparing'||x.phase==='scheduled')&&weddingStyleKey(x.style)===style&&!x.cancelledAt&&!x.supersededAt).sort((a,b)=>(+b.time||0)-(+a.time||0))[0]||null,record=weddingLatestRecord(c,style),stored=record&&weddingPreparedForRecord(record),red=style==='chinese'?' wedding-offline-entry-chinese':'',small=style==='chinese'?'CHINESE CEREMONY':'PRIVATE CEREMONY';if(ready)return '<section class="wedding-offline-entry'+red+'"><div class="wedding-offline-copy"><small>'+small+'</small><b>'+label+'婚礼仪式</b><span>和 '+esc(weddingRoleName(c))+' 的整场婚礼已经准备完成</span></div><div class="wedding-offline-actions wedding-offline-actions-ready"><button type="button" class="primary" onclick="event.stopPropagation();closeModal();weddingOpenReadyInvite(\''+c.id+'\',\''+ready.id+'\')">进入婚礼</button>'+(weddingPrivateApp()?'<button type="button" onclick="event.stopPropagation();closeModal();weddingStartSimulation(\''+c.id+'\',\''+ready.id+'\',\''+style+'\')">模拟一次 · 不保存</button>':'')+'<button type="button" onclick="event.stopPropagation();weddingOpenSceneRegenerator(\''+c.id+'\',\''+ready.id+'\')">单独重做某一章</button><button type="button" onclick="event.stopPropagation();closeModal();weddingRegenerate(\''+c.id+'\',\''+style+'\')">重新生成'+label+'婚礼</button></div></section>';if(pending){const prepared=weddingState().prepared[pending.id]||weddingState().prepared[pending.preparedId],due=pending.phase==='scheduled'&&prepared&&Date.now()>=+pending.eventAt;if(due)return '<section class="wedding-offline-entry'+red+'"><div class="wedding-offline-copy"><small>'+small+'</small><b>'+label+'婚礼已准备就绪</b><span>邀请在 App 挂起时暂停发送，点击即可继续</span></div><button type="button" class="primary" onclick="event.stopPropagation();weddingRecoverReadyInvite(\''+c.id+'\',\''+pending.id+'\')">立即进入婚礼</button></section>';const scheduled=pending.phase==='scheduled',status=scheduled?'<span data-wedding-countdown="'+pending.eventAt+'">'+esc(weddingCountdownText(pending.eventAt))+'</span>':'<span data-wedding-preparing="'+pending.id+'">'+esc(weddingPrepTimeText(pending))+'</span>';return '<section class="wedding-offline-entry'+red+'"><div class="wedding-offline-copy"><small>'+small+'</small><b>'+label+(scheduled?'婚礼已准备就绪':'婚礼后台准备中')+'</b>'+status+(scheduled?'':'<em class="wedding-stay-note">准备期间请不要退出小手机或锁屏</em>')+'</div><button type="button" onclick="event.stopPropagation();'+(scheduled?'weddingRecoverReadyInvite(\''+c.id+'\',\''+pending.id+'\')':'toast(\'整场准备完成后，他会发来可进入的邀请卡\')')+'">'+(scheduled?'等待十秒后进入':'等待他发来邀请')+'</button></section>';}if(record&&stored)return '<section class="wedding-offline-entry'+red+'"><div class="wedding-offline-copy"><small>'+small+'</small><b>'+label+'婚礼仪式</b><span>已保留这场婚礼的婚书与六幕画面</span></div><div class="wedding-offline-actions wedding-offline-actions-ready"><button type="button" class="primary" onclick="event.stopPropagation();weddingOpenStoredCeremony(\''+c.id+'\',\''+record.id+'\')">再次进入婚礼</button><button type="button" onclick="event.stopPropagation();weddingOpenSceneRegenerator(\''+c.id+'\',\''+record.id+'\')">单独重做某一章</button><button type="button" onclick="event.stopPropagation();closeModal();weddingRegenerate(\''+c.id+'\',\''+style+'\')">重新生成'+label+'婚礼</button></div></section>';return '<section class="wedding-offline-entry'+red+'"><div class="wedding-offline-copy"><small>'+small+'</small><b>'+label+'婚礼仪式</b><span>先一次性准备完整台词与六幕画面，完成后由他发来邀请</span></div><button type="button" class="primary" onclick="event.stopPropagation();closeModal();weddingRegenerate(\''+c.id+'\',\''+style+'\')">后台准备'+label+'婚礼</button></section>';};
const weddingOfflineStyleHTMLBeforeDeletedCardRecovery=weddingOfflineStyleHTML;
weddingOfflineStyleHTML=function(c,style){
  style=weddingStyleKey(style);
  const ready=weddingLatestReadyInvite(c,style);
  if(ready)return weddingOfflineStyleHTMLBeforeDeletedCardRecovery(c,style);
  const pending=msgs(c.id).filter(x=>x&&x.type==='weddinginvite'&&(x.phase==='preparing'||x.phase==='scheduled')&&weddingStyleKey(x.style)===style&&!x.cancelledAt&&!x.supersededAt).sort((a,b)=>(+b.time||0)-(+a.time||0))[0]||null;
  const ref=pending?weddingResolvePreparedInvite(c,pending):weddingLatestPreparedEntry(c,style);
  const record=weddingLatestRecord(c,style),stored=record&&weddingPreparedForRecord(record);
  if(record&&stored&&!pending)return weddingOfflineStyleHTMLBeforeDeletedCardRecovery(c,style);
  if(!ref)return weddingOfflineStyleHTMLBeforeDeletedCardRecovery(c,style);
  const label=style==='chinese'?'中式':'现代',red=style==='chinese'?' wedding-offline-entry-chinese':'',small=style==='chinese'?'CHINESE CEREMONY':'PRIVATE CEREMONY',readyAt=weddingPreparedReadyAt(ref,pending),due=Date.now()>=readyAt,token=pending&&pending.id||ref.id;
  if(due)return '<section class="wedding-offline-entry'+red+'"><div class="wedding-offline-copy"><small>'+small+'</small><b>'+label+'婚礼已准备就绪</b><span>原邀请卡即使已经删除，也可以从这里继续进入或重新准备</span></div><div class="wedding-offline-actions wedding-offline-actions-ready"><button type="button" class="primary" onclick="event.stopPropagation();closeModal();weddingRecoverReadyInvite(\''+c.id+'\',\''+token+'\',\''+style+'\')">立即进入婚礼</button>'+(weddingPrivateApp()?'<button type="button" onclick="event.stopPropagation();closeModal();weddingStartSimulation(\''+c.id+'\',\''+token+'\',\''+style+'\')">模拟一次 · 不保存</button>':'')+'<button type="button" onclick="event.stopPropagation();weddingOpenSceneRegenerator(\''+c.id+'\',\''+token+'\')">单独重做某一章</button><button type="button" onclick="event.stopPropagation();closeModal();weddingRegenerate(\''+c.id+'\',\''+style+'\')">重新生成'+label+'婚礼</button></div></section>';
  return '<section class="wedding-offline-entry'+red+'"><div class="wedding-offline-copy"><small>'+small+'</small><b>'+label+'婚礼已准备就绪</b><span data-wedding-countdown="'+readyAt+'">'+esc(weddingCountdownText(readyAt))+'</span></div><button type="button" onclick="event.stopPropagation();weddingRecoverReadyInvite(\''+c.id+'\',\''+token+'\',\''+style+'\')">等待十秒后进入</button></section>';
};
weddingOfflineEntryHTML=function(){const c=weddingInvitationRole();if(!c)return '<section class="wedding-offline-entry wedding-offline-entry-disabled"><div class="wedding-offline-copy"><small>PRIVATE CEREMONY</small><b>婚礼仪式</b><span>婚礼只对情侣空间绑定的角色开放</span></div><button type="button" onclick="event.stopPropagation();toast(\'请先在情侣空间绑定婚礼角色\')">尚未绑定情侣角色</button></section>';const clear=weddingHasStoredData(c)?'<button type="button" class="wedding-clear-all" onclick="event.stopPropagation();weddingClearAll(\''+c.id+'\')">清空所有婚礼记忆、婚书与夫妻关系</button>':'';return '<div class="wedding-offline-styles">'+weddingOfflineStyleHTML(c,'modern')+weddingOfflineStyleHTML(c,'chinese')+clear+'</div>';};

function weddingFitCertificateTitle(){const title=document.querySelector('.wedding-cert-content h2'),content=document.querySelector('.wedding-cert-content');if(!title||!content)return;title.style.width='max-content';title.style.maxWidth='none';title.style.transform='none';let size=Math.min(27,parseFloat(getComputedStyle(title).fontSize)||27),max=Math.max(180,content.clientWidth-18);title.style.fontSize=size+'px';while(size>18&&title.getBoundingClientRect().width>max){size-=.5;title.style.fontSize=size+'px';}title.style.width='100%';title.style.maxWidth='100%';title.style.textAlign='center';title.style.marginLeft='auto';title.style.marginRight='auto';}
function weddingOpen(cid,source){try{if(typeof audioUnlock==='function')audioUnlock();}catch(_){}W.view='setup';W.session=null;W.busy=false;const st=weddingState();W.selectedCid=cid||st.lastCid||((S.couple&&S.couple.cid)||'');const roles=weddingRoles();if(!roles.some(c=>c.id===W.selectedCid))W.selectedCid=roles[0]&&roles[0].id||'';W.entrySource=source||'app';weddingRenderSetup();}
function weddingClose(){clearTimeout(W.typingTimer);clearTimeout(W.sceneTimer);W.typingTimer=0;W.stageReady=false;W.scene='';weddingMusicStop();const root=weddingRoot();if(root)root.remove();}
function weddingRenderSetup(){const roles=weddingRoles(),imageReady=weddingImageReady(),disabled=!W.selectedCid?' disabled':'',simulate=weddingPrivateApp()?'<div class="wedding-style-starts wedding-style-simulations"><button class="wedding-start wedding-simulate-start"'+disabled+' onclick="weddingStart(\'simulation\',\'modern\')">模拟现代</button><button class="wedding-start wedding-simulate-start chinese"'+disabled+' onclick="weddingStart(\'simulation\',\'chinese\')">模拟中式</button></div><div class="wedding-simulate-note">两种模拟都不收藏婚书、不写记忆、不改变关系、不发送婚后消息；没有已完成内容时会先转入后台准备</div>':'';weddingMount('<section class="wedding-setup"><div class="wedding-setup-head"><button class="wedding-icon-btn" onclick="weddingClose()" aria-label="退出">‹</button><span></span></div><div class="wedding-kicker">OUR WEDDING · PRIVATE</div><h1>此刻，只属于你们</h1><p class="wedding-setup-lead">选择现代或中式；后台一次性完成整套台词和六幕画面，全部准备好后角色再发来可直接进入的邀请卡。</p><div class="wedding-role-title"><b>选择婚礼对象</b><span>全程纯点击字幕</span></div><div class="wedding-role-list">'+(roles.length?roles.map(c=>'<button class="wedding-role '+(c.id===W.selectedCid?'on':'')+'" onclick="weddingSelectRole(\''+c.id+'\')">'+av(c.avatar,'sm')+'<span class="wedding-role-copy"><b>'+esc(weddingRoleName(c))+'</b><small>纯字幕 · 点击继续</small></span><span class="wedding-role-check">✓</span></button>').join(''):'<div class="empty" style="padding:28px 10px">先在情侣空间绑定一个角色，才能准备婚礼。</div>')+'</div><div class="wedding-style-starts"><button class="wedding-start"'+disabled+' onclick="weddingStart(\'prepare\',\'modern\')">后台准备现代</button><button class="wedding-start chinese"'+disabled+' onclick="weddingStart(\'prepare\',\'chinese\')">后台准备中式</button></div>'+simulate+'<div class="wedding-setup-note">'+(imageReady?'预计约 11 分钟；某一幕失败会只重试该幕，仍失败才使用对应预置图。':'无需等待生图：将直接装入六张动作一致的预置演出图，仍会先把整场内容准备完整。')+'</div></section>');}
function weddingSelectRole(cid){W.selectedCid=cid;weddingRenderSetup();}
function weddingShowNameCard(c){const s=W.session;if(!s)return;const chinese=s.style==='chinese',title=chinese?'良辰既定 · 共书婚名':'Before We Begin',sub=chinese?'请写下今日婚书上的名字':'Write the names that will appear on your certificate';weddingMount('<section class="wedding-name-screen '+(chinese?'chinese':'modern')+'"><div class="wedding-name-glow"></div><div class="wedding-name-card"><small>'+(chinese?'CHINESE WEDDING':'OUR WEDDING')+'</small><h2>'+title+'</h2><p>'+sub+'</p><label><span>新娘</span><input id="weddingBrideName" maxlength="20" value="'+esc(s.brideName)+'" placeholder="你的名字"></label><label><span>新郎</span><input id="weddingGroomName" maxlength="20" value="'+esc(s.groomName)+'" readonly></label><button onclick="weddingBeginCeremony()">'+(chinese?'入喜堂':'进入仪式')+'</button><em>'+(s.simulation?'模拟模式 · 本次不会保存':'名字只用于本次婚礼与婚书')+'</em></div></section>');}
function weddingBeginCeremony(){const s=W.session,c=s&&getC(s.cid);if(!s||!c)return weddingClose();const bride=document.getElementById('weddingBrideName');s.brideName=weddingSafeText(bride&&bride.value,s.brideName||'我',20);s.groomName=weddingRoleOriginalName(c);try{if(typeof audioUnlock==='function')audioUnlock();}catch(_){}weddingMusicPlay(true);W.opening=true;W.stageReady=false;W.scene='';weddingRenderStory();}

function weddingFallback(c){const n=weddingRoleName(c);return{formalwear:'black',opening_narration:'玻璃穹顶映着晚霞，花瓣沿着长廊轻轻落下。人群安静下来，只有'+n+'朝你伸出手。',opening_line:'别看别人。今天，你只需要看着我。',hand_prompt:'走到他面前时，你想怎样把手交给他？',hand_choices:[{text:'握紧他的手，轻声说“我来了”',response:'嗯，我等到你了。这一次，我不会再松开。'},{text:'故意停住，问他会不会后悔',response:'会紧张，会害怕，但唯独不会后悔选择你。'}],aisle_narration:'你们牵着手走过铺满白色花瓣的长廊。乐声很轻，他的拇指始终安抚似的摩挲着你的指节。',aisle_line:'慢一点也没关系。我们有一辈子的时间。',officiant_line:'请你们看着彼此，回答这一生最郑重的问题：无论顺境或低谷，是否愿意继续选择对方？',vow_prompt:'轮到你回答誓言时，你想对他说什么？',vow_choices:[{text:'“我愿意，也愿意一直偏爱你。”',response:'这句话我会记一辈子。以后换我一次次证明给你看。'},{text:'“不只今天，以后的每一天都愿意。”',response:'好。那以后每一天醒来，我都重新向你求一次婚。'}],vow_narration:'他双手拿着展开的誓词纸，正面望着你。开口前停了两秒，仍然没有移开目光。',vow_line:'我不能许诺生活永远平静，但我许诺每一次风雨里，我都会站在你这一边。',kiss_narration:'他托住你的指尖，俯身在你的手背落下一个很轻、很郑重的吻。掌心的温度沿着指节传来。',kiss_line:'这个吻不是礼节，是我把余生交给你的证明。',ring_prompt:'戒指就在他掌心，你想让这一刻怎样继续？',ring_choices:[{text:'先替他戴上戒指',response:'原来被你套牢的感觉，是这样。很好，我很喜欢。'},{text:'向他伸出左手',response:'交给我。我会戴得很慢，让你记住这一秒。'}],ring_narration:'他把戒指缓缓戴过你左手的指尖，停在无名指上。银色边缘接住灯光，也接住四周的掌声。',ring_line:'戴上以后，就不许假装今天只是一场梦。',blessing_narration:'亲友的祝福从四周涌来。有人笑着鼓掌，也有人悄悄擦去眼泪，而他正面拥住你，仍只看着你。',blessing_line:'以往的故事到这里不是结局。从今天起，你们将共同书写往后的每一页。',ending_narration:'音乐重新响起，他拥着你走向长廊尽头。身后的花瓣落下，像替这一刻盖上温柔的印章。',ending_line:'走吧，新娘。我们的以后，现在开始。',certificate_vow:'愿往后的每一次欢笑与风雨，都有我在你身旁。'};}
const weddingFallbackBeforeRingOrder=weddingFallback;
weddingFallback=function(c){const out=weddingFallbackBeforeRingOrder(c);out.kiss_narration='婚戒在指间映着光，他托住你的手，在手背落下郑重的一吻。';out.kiss_line='戒指戴好了。这个吻，是我把余生也一起交给你的证明。';return out;};
function weddingJSON(raw){const t=String(raw||'').replace(/```json\s*/gi,'').replace(/```/g,'').trim(),a=t.indexOf('{'),b=t.lastIndexOf('}');if(a<0||b<=a)throw new Error('no-json');return JSON.parse(t.slice(a,b+1));}
function weddingLooksNarration(text){const t=String(text||'').replace(/\s+/g,' ').trim();if(!t)return false;if(/^[“"「『].+[”"」』]$/.test(t))return false;const thirdPerson=/(?:^|[，。；！？])(?:你|他|她|两人|你们|人群|宾客|司仪|音乐|花瓣|灯光|掌声|长廊|玻璃穹顶)/.test(t),action=/(?:目光|视线|指尖|掌心|脚步|声音|呼吸|神情|眉眼|唇角|停了|落下|抬起|低下|俯身|走近|握住|牵住|托住|戴上|拥住|看着|望着|念|摩挲|轻颤|响起|安静下来)/.test(t),selfVoice=/^(?:我|别|今天|以后|这一次|交给我|慢一点|走吧|好[，。]|嗯[，。]|愿|请你|嫁给我|答应我)/.test(t);return !selfVoice&&thirdPerson&&action;}
function weddingNormalizeChoices(raw,fallback){const list=Array.isArray(raw)?raw:[];return[0,1].map(i=>{const response=weddingSafeText(list[i]&&list[i].response,fallback[i].response,WEDDING_DIALOGUE_MAX);return{text:weddingSafeText(list[i]&&list[i].text,fallback[i].text,28),response:weddingLooksNarration(response)?fallback[i].response:response};});}
function weddingLineMatchesScene(field,text){const scene=WEDDING_FIELD_SCENES[field],t=String(text||'');if(!scene)return true;const forbidden={welcome:/戒指|无名指|亲吻|吻.{0,3}手背|拥抱|誓词纸/,aisle:/吻.{0,3}手背|亲吻|无名指|戴.{0,3}戒指|誓词纸|拥抱/,vow:/无名指|戴.{0,3}戒指|亲吻|吻.{0,3}手背|拥抱/,ring:/亲吻|吻.{0,3}手背|拥抱|誓词纸/,kiss:/拥抱|誓词纸|再次.{0,3}戴.{0,3}戒指/,embrace:/戴.{0,3}戒指|无名指|吻.{0,3}手背|誓词纸/};if(forbidden[scene]&&forbidden[scene].test(t))return false;if(field==='kiss_narration'&&!/手背/.test(t))return false;if(field==='ring_narration'&&(!/戒指/.test(t)||!/无名指/.test(t)))return false;if(field==='vow_narration'&&!/(双手|两手).{0,8}(誓词|纸)|(?:誓词|纸).{0,8}(双手|两手)/.test(t))return false;return true;}
function weddingNormalize(data,c){const f=weddingFallback(c),fixed=weddingFixedNarrations('modern'),out={},fields=['opening_narration','opening_line','hand_prompt','aisle_narration','aisle_line','officiant_line','vow_prompt','vow_narration','vow_line','kiss_narration','kiss_line','ring_prompt','ring_narration','ring_line','blessing_narration','blessing_line','ending_narration','ending_line','certificate_vow'];fields.forEach(k=>{const locked=k.includes('narration')||k.includes('prompt')||k==='officiant_line'||k==='blessing_line',fallback=fixed[k]||f[k],value=locked?fallback:weddingSafeText(data&&data[k],fallback,k==='certificate_vow'?55:WEDDING_DIALOGUE_MAX);out[k]=weddingLineMatchesScene(k,value)?value:fallback;});const roleLines=['opening_line','aisle_line','vow_line','kiss_line','ring_line','ending_line'];for(const lineKey of roleLines)if(weddingLooksNarration(out[lineKey]))out[lineKey]=f[lineKey];const fw=String(data&&data.formalwear||'').toLowerCase();out.formalwear=/white|ivory|白/.test(fw)?'white':/black|黑/.test(fw)?'black':f.formalwear;out.hand_choices=weddingNormalizeChoices(data&&data.hand_choices,f.hand_choices);out.vow_choices=weddingNormalizeChoices(data&&data.vow_choices,f.vow_choices);out.ring_choices=weddingNormalizeChoices(data&&data.ring_choices,f.ring_choices);return out;}
async function weddingGenerate(c){const contracts=WEDDING_SCENE_ORDER.map(k=>'【'+WEDDING_SCENE_CONTRACTS[k].title+'】'+WEDDING_SCENE_CONTRACTS[k].must+'；'+WEDDING_SCENE_CONTRACTS[k].forbid).join('\n');const prompt='你正在与“'+(S.me&&S.me.name||'我')+'”举行一场完整的现代婚礼。用户是新娘，所有关键画面采用新娘第一人称视角。旁白、司仪词和每一幕的问题已经固定；你要依据本人设定、说话习惯、真实关系与记忆，生成你亲口对恋人说的话，同时为每次互动生成两个符合当下关系的用户选项，并为每个选项分别生成你会亲口说出的对应回应。台词必须与当幕动作完全对口，不能提前或滞后描述其他动作。\n'+contracts+'\n礼服规则：忽略人物设定中的所有日常穿搭。请根据人物气质在正式黑色新郎礼服与正式象牙白新郎礼服中自行选择一种，并在 formalwear 字段只写 black 或 white；整场婚礼固定这一套，不得中途换色。hand_choices、vow_choices、ring_choices 都必须恰好两个对象，每个对象含 text 和 response：text 是用户可点击说出或做出的短选项，response 是你只针对同一个 text 亲口给出的回应，两个选项与回应不得串位、不得重复。所有 line 与 response 只能是你本人亲口说出的原话，禁止旁白、第三人称动作、括号动作，以及“他看着你、他的目光、声音更低”等描写。不要输出 narration、prompt、officiant 或 blessing 字段，不要提系统、网页、模型、按钮、图片或设定，不输出 Markdown。只输出 JSON：formalwear, opening_line, hand_choices（两个对象，每个含 text,response）, aisle_line, vow_choices（两个对象，每个含 text,response）, vow_line, kiss_line, ring_choices（两个对象，每个含 text,response）, ring_line, ending_line, certificate_vow。角色台词10到42字，选项不超过24字；certificate_vow 只写一句18到40字、符合你说话习惯的专属婚书结语。';const raw=await chatAPI([{role:'system',content:buildSystem(c)},{role:'user',content:prompt}],{aux:false,max:1650,temp:.78,complete:true});return weddingNormalize(weddingJSON(raw),c);}

function weddingChineseFallback(c){const n=weddingRoleName(c);return{formalwear:'red',opening_narration:'花轿停在喜堂门前，帘外锣鼓渐歇。红帘被轻轻挑开，'+n+'俯身望向你，朝你递来手。',opening_line:'良辰已至。把手给我，我接你下轿。',hand_prompt:'红帘之外，他仍等着你的回应。',hand_choices:[{text:'把手郑重交给他',response:'慢些走。有我在，今日往后都不会让你独行。'},{text:'隔着红帘轻声唤他',response:'我在。你唤一声，我便应你一生。'}],silk_narration:'你与他各执红绣球的一端，并肩步入灯火通明的喜堂。红绸在两人之间轻轻晃动，像牵住了往后的岁月。',silk_line:'这一端我握紧了，余生也不会松。',heaven_officiant:'一拜天地——',heaven_narration:'他转向喜堂正前方，与你一同俯身，敬天地为证。',heaven_line:'天地既鉴，此心此诺，永不相负。',high_officiant:'二拜高堂——',high_narration:'同一盏烛火映着他的侧脸。你们再次俯身，敬来路、敬亲恩，也敬此后共同的家。',high_line:'今日承亲恩成礼，往后我会护好我们的家。',couple_officiant:'夫妻对拜——',couple_narration:'他转身面向你，隔着红绸郑重俯首。四周喧声渐远，只余你们彼此这一拜。',couple_line:'这一拜，不止今日。往后晨昏岁岁，我都与你相对。',toast_narration:'喜堂烛影摇红，你们各自举起金色酒杯，在彼此面前轻轻相碰。',toast_line:'以此杯敬你，也敬我们此后同心同归。',veil_narration:'夜色渐深，你坐在铺着红锦的婚床上。他执起喜秤，让顶端轻轻托住盖头前缘，缓缓向上挑起。',veil_line:'今日终于能好好看你。夫人，往后请多指教。',ending_narration:'红盖头落在一旁，烛火将你们的影子映在一起。礼数至此圆满，新的岁月也从此刻启程。',ending_line:'礼成了。你我一诺，此生作数。',certificate_vow:'愿与你白首同心，朝朝暮暮相守，岁岁年年不负。'};}
function weddingChineseNormalize(data,c){const f=weddingChineseFallback(c),fixed=weddingFixedNarrations('chinese'),out={formalwear:'red'},fields=['opening_narration','opening_line','hand_prompt','silk_narration','silk_line','heaven_officiant','heaven_narration','heaven_line','high_officiant','high_narration','high_line','couple_officiant','couple_narration','couple_line','toast_narration','toast_line','veil_narration','veil_line','ending_narration','ending_line','certificate_vow'];for(const k of fields){const locked=k.includes('narration')||k.includes('prompt')||k.includes('officiant'),fallback=fixed[k]||f[k];out[k]=locked?fallback:weddingSafeText(data&&data[k],fallback,k==='certificate_vow'?55:WEDDING_DIALOGUE_MAX);}out.hand_choices=weddingNormalizeChoices(data&&data.hand_choices,f.hand_choices);out.heaven_officiant='一拜天地——';out.high_officiant='二拜高堂——';out.couple_officiant='夫妻对拜——';return out;}
async function weddingGenerateChinese(c){const contracts=WEDDING_CHINESE_SCENE_ORDER.map(k=>'【'+WEDDING_CHINESE_SCENE_CONTRACTS[k].title+'】'+WEDDING_CHINESE_SCENE_CONTRACTS[k].must+'；'+WEDDING_CHINESE_SCENE_CONTRACTS[k].forbid).join('\n');const prompt='你正在与“'+(S.me&&S.me.name||'我')+'”举行一场现实中的中式婚礼。旁白、司礼词和问题已经固定；你要依据本人的性格、关系、记忆与说话习惯，生成自己亲口对恋人说的偏古风但自然可懂的台词，同时为花轿迎亲互动生成两个用户选项，并分别生成你针对同一选项会亲口说出的回应。流程固定为：花轿迎新娘下轿、牵红绣球入喜堂、一拜天地、二拜高堂、夫妻对拜、双方碰杯敬酒、用喜秤挑盖头、签中式婚书；每句台词必须与当幕动作完全对口。\n'+contracts+'\n整场固定红色中式新郎喜服、古风长发和传统发冠；人设明确为白发或银白发时沿用白色长发，否则使用黑色长发。hand_choices 必须恰好两个对象，每个含 text 和 response：text 是用户可点击说出或做出的偏古风短选项，response 是你只针对同一个 text 亲口给出的回应；不得串位或重复。所有 line 与 response 只能是你本人亲口说出的原话，禁止旁白、第三人称动作、括号动作及绘图说明。不要输出 narration、prompt 或 officiant 字段，不要提系统、模型、程序、图片或画面，不要 Markdown。只输出 JSON：opening_line, hand_choices（两个对象，每个含 text,response）, silk_line, heaven_line, high_line, couple_line, toast_line, veil_line, ending_line, certificate_vow。角色台词10到42字，选项不超过24字；certificate_vow 只写一句18到40字。';const raw=await chatAPI([{role:'system',content:buildSystem(c)},{role:'user',content:prompt}],{aux:false,max:1450,temp:.78,complete:true});return weddingChineseNormalize(weddingJSON(raw),c);}

function weddingChineseHairColor(c){const raw=[c&&c.imgLock,c&&c.persona].filter(Boolean).join('。');return /白毛|银毛|白(?:色|银)?(?:长)?发|银白(?:色)?(?:长)?发|银(?:色)?(?:长)?发|white\s+hair/i.test(raw)?'white':'black';}
function weddingChineseHairText(c){return weddingChineseHairColor(c)==='white'?'银白色古风长发':'纯黑色古风长发';}
function weddingAppearanceProfile(c,style){style=weddingStyleKey(style);const raw=[c&&c.imgLock,c&&c.persona].filter(Boolean).join('。').replace(/\s+/g,' '),parts=raw.split(/[。；;\n]/).map(x=>x.trim()).filter(Boolean),look=/发型|头发|刘海|发色|眼睛|瞳|眼型|眉|鼻|唇|嘴|脸|轮廓|肤色|皮肤|痣|雀斑|身高|肩|体型|年龄|成年|男性|气质/,clothes=/穿搭|日常穿|常穿|衣服|上衣|外套|卫衣|衬衫|毛衣|夹克|裙|牛仔|鞋|裤|领带|西装|礼服/,hair=/发型|头发|刘海|发色|短发|长发|金发|白发|银发|棕发|红发|蓝发/;let picked=parts.filter(x=>look.test(x)&&!clothes.test(x)&&(style!=='chinese'||!hair.test(x))).join('；');if(!picked)picked=parts.filter(x=>!clothes.test(x)&&(style!=='chinese'||!hair.test(x))).slice(0,2).join('；');const hairRule=style==='chinese'?'；发型按该角色气质独立设计，但强制为'+weddingChineseHairText(c)+'并佩戴传统发冠；只有人设明确写白发、银发或银白发才使用白色，否则默认黑色；同一场六幕的具体束发结构、刘海分缝、发色、发冠造型必须完全一致；不同角色可拥有不同长发造型和不同脸':'';return ('成年男性；'+(picked||'外貌严格依据该角色既有五官、肤色和体型')+hairRule+'；身份锚点 '+weddingHash((c&&c.id||'role')+'|'+raw+'|'+style)).slice(0,520);}
function weddingImageReady(){const ch=S.settings&&S.settings.chat||{},base=(S.settings&&S.settings.imgBase)||ch.base,key=(S.settings&&S.settings.imgKey)||ch.key;return !!(base&&key&&typeof imageGenerateExternal==='function');}
function weddingFormalwearText(v){return v==='white'?'象牙白色正式新郎礼服（ivory white formal groom tuxedo）':'黑色正式新郎礼服（black formal groom tuxedo）';}
function weddingBuildImagePrompt(c,scene,formalwear,extra,style){style=weddingStyleKey(style);const ct=weddingContracts(style)[scene]||weddingContracts(style)[weddingSceneOrder(style)[0]],identity=weddingAppearanceProfile(c,style),chinese=style==='chinese',wear=chinese?'固定红色中式新郎喜服（traditional red Chinese groom wedding robe）':weddingFormalwearText(formalwear),hairText=chinese?weddingChineseHairText(c):'';return ('竖版 2:3，精致高质量日系动漫插画，'+(chinese?'古代中式婚礼喜堂，红金烛火与传统婚俗氛围':'现代玻璃花房婚礼，柔和电影光线')+'，沉浸式视觉小说CG。\n【同一人物身份锁】'+identity+'。六张图必须是同一个成年男性，新郎的脸型、五官、肤色、瞳色、具体发型结构、发色、发冠和体型全程一致；不同角色的身份锚点不同，脸与发型设计必须随各自人设变化，绝不能套用同一张脸。\n【礼服与头发硬规则】整场固定穿'+wear+'。'+(chinese?'必须为'+hairText+'、传统发冠、红色喜服；头发必须明显过肩，严禁短发、现代发型、与人设冲突的发色和现代西装。除人设明确指定白发、银发或银白发时保留白色之外，其他日常发型与日常穿搭一律忽略。':'只允许正式黑色或象牙白色新郎礼服，完全忽略人物设定中的日常穿搭。')+'\n【新娘视角硬规则】镜头就是新娘的眼睛。不得出现新娘正脸或第三人称全身；只在动作必要时出现镜头前的新娘手部、头纱或肩部边缘。\n【本张唯一动作】'+ct.action+'\n【必须看见】'+ct.must+'。\n【禁止】'+ct.forbid+' 不得多手、多指、错位肢体，不得出现文字、字幕、水印、Logo。画面必须只表达本张动作，不得偷跑下一幕。'+(extra?'\n【本张重试纠正与身份参考】'+extra+' 参考图是绝对身份标准：具体脸型、五官比例、刘海分缝、束发结构、每一缕长发、发色、发冠外形与喜服纹样必须一模一样，只改变动作和镜头。':'')).slice(0,3500);}
function weddingSceneKey(c,scene,formalwear,generationId,style){style=weddingStyleKey(style);return '__wedding_cg_v7_'+weddingHash((c&&c.id||'')+'|'+weddingAppearanceProfile(c,style)+'|'+style+'|'+scene+'|'+formalwear+'|'+(generationId||W.generationId||'first'));}
async function weddingVerifyImage(src,c,scene,formalwear,referenceNote,style){style=weddingStyleKey(style);if(typeof visionAPI!=='function')return{pass:true,reason:'未配置视觉复核'};const ct=weddingContracts(style)[scene],chinese=style==='chinese';try{const raw=await visionAPI(src,'只做婚礼CG质检。检查：1）是否为成年男性新郎；2）是否穿'+(chinese?'固定红色中式新郎喜服，并且是'+weddingChineseHairText(c)+'、明显过肩、佩戴传统发冠，绝无短发、错误发色或现代西装':weddingFormalwearText(formalwear)+'且没有日常穿搭')+'；3）是否严格完成“'+ct.must+'”；4）是否违反“'+ct.forbid+'”；5）是否为新娘第一人称且不出现新娘正脸；6）手指和肢体是否明显错误。'+(referenceNote?'7）与同场参考必须是同一个人：脸型、五官比例、具体刘海分缝、束发结构、长发轮廓、发色、发冠造型、礼服领型与纹样都必须一模一样，不能只做到大致相似。参考摘要：“'+referenceNote+'”。':'')+'只输出 JSON：{"pass":true或false,"reason":"不通过时用一句中文说清最关键错误"}。'),d=weddingJSON(raw);return{pass:d.pass===true,reason:weddingSafeText(d.reason,'动作、身份或礼服未通过复核',120)};}catch(_){return{pass:true,reason:'视觉复核不可用'};}}
function weddingIdentityReference(scene,style){style=weddingStyleKey(style);const first=weddingSceneOrder(style)[0],src=W.sceneImages[first];return src?{scene:first,src}:null;}
function weddingReferenceNoteKey(ref,formalwear,style){return weddingStyleKey(style)+'|'+String(W.generationId||'first')+'|'+String(ref&&ref.scene||'first')+'|'+String(formalwear||'black');}
async function weddingReferenceIdentityNote(ref,c,formalwear,style){style=weddingStyleKey(style);if(!ref||!ref.src)return'';W.referenceNotes=W.referenceNotes||{};const cacheKey=weddingReferenceNoteKey(ref,formalwear,style);if(Object.prototype.hasOwnProperty.call(W.referenceNotes,cacheKey))return W.referenceNotes[cacheKey];const note=(weddingAppearanceProfile(c,style)+'；固定礼服：'+(style==='chinese'?'红色中式新郎喜服、传统发冠、'+weddingChineseHairText(c):weddingFormalwearText(formalwear))+'；第一幕身份锚点保持不变').slice(0,520);W.referenceNotes[cacheKey]=note;return note;}
async function weddingGenerateWithReference(base,key,model,prompt,referenceSrc){const identityPrompt=prompt+'\n\n费用与兼容规则：本次只允许发起一次普通生图请求，不得再调用聊天参考图生图。请严格依据上面的第一幕身份摘要延续同一个新郎，只改变本幕动作和镜头。';const result=await imageGenerateExternal(base,key,model,identityPrompt,'1024x1536','high',{allowChatFallback:false,timeoutMs:300000});result.identitySummaryOnly=!!referenceSrc;return result;}
async function weddingGenerateScene(c,scene,formalwear,opt){opt=opt||{};const style=weddingStyleKey(opt.style),contracts=weddingContracts(style),ch=S.settings&&S.settings.chat||{},base=((S.settings&&S.settings.imgBase)||ch.base||'').replace(/\/+$/,''),key=(S.settings&&S.settings.imgKey)||ch.key||'',model=(S.settings&&S.settings.imgModel)||'gpt-image-2';if(!base||!key)throw new Error('未配置生图接口');const reference=opt.reference||null,referenceNote=reference?await weddingReferenceIdentityNote(reference,c,formalwear,style):'',extra=[opt.reason||'',referenceNote&&('参考画面 '+contracts[reference.scene].title+' 的身份摘要：'+referenceNote+'。具体脸型、五官、发型结构、发冠和礼服必须一模一样。')].filter(Boolean).join(' '),prompt=weddingBuildImagePrompt(c,scene,formalwear,extra,style),result=reference?await weddingGenerateWithReference(base,key,model,prompt,reference.src):await imageGenerateExternal(base,key,model,prompt,'1024x1536','high',{allowChatFallback:false,timeoutMs:300000}),src=await stableImageSrc(result.url),check={pass:true,reason:'图片平台已返回，未再发起联网复核'};if(!src)throw new Error('图片平台没有返回可显示的图片');W.sceneRoutes=W.sceneRoutes||{};W.sceneRoutes[scene]=result.endpoint||'images-generations';W.sceneVerify[scene]=check;return src;}
function weddingPrepareScene(c,scene,formalwear,deferFallback,style){style=weddingStyleKey(style);const scenes=weddingScenes(style);if(W.sceneImages[scene])return Promise.resolve(W.sceneImages[scene]);if(W.sceneJobs[scene])return W.sceneJobs[scene];const job=(async()=>{if(!weddingImageReady()){W.sceneImages[scene]=scenes[scene];return W.sceneImages[scene];}const key=weddingSceneKey(c,scene,formalwear,W.generationId,style);try{const cached=typeof imgGet==='function'?await imgGet(key):null;if(cached){W.sceneImages[scene]=cached.src||cached;W.sceneVerify[scene]=cached.verified||{pass:true,reason:'缓存'};return W.sceneImages[scene];}const first=weddingSceneOrder(style)[0],reference=scene===first?null:weddingIdentityReference(scene,style),src=await weddingGenerateScene(c,scene,formalwear,{style,reference});W.sceneImages[scene]=src;if(typeof imgPut==='function')await imgPut(key,{src,verified:W.sceneVerify[scene],createdAt:Date.now(),referenceScene:reference&&reference.scene||''});return src;}catch(e){W.sceneFailures[scene]=String(e&&e.weddingReason||e&&e.message||e).slice(0,160);if(e&&e.weddingCandidate){W.sceneCandidates=W.sceneCandidates||{};W.sceneCandidates[scene]={src:e.weddingCandidate,verify:e.weddingCandidateVerify||{pass:false,reason:W.sceneFailures[scene]},referenceScene:scene===weddingSceneOrder(style)[0]?'':weddingSceneOrder(style)[0]};W.sceneVerify[scene]=e.weddingCandidateVerify||{pass:false,reason:W.sceneFailures[scene]};}else W.sceneVerify[scene]={pass:false,reason:W.sceneFailures[scene]};if(deferFallback)return'';W.sceneImages[scene]=scenes[scene];return W.sceneImages[scene];}finally{delete W.sceneJobs[scene];}})();W.sceneJobs[scene]=job;return job;}
async function weddingRetryFailedScene(c,scene,formalwear,style){style=weddingStyleKey(style);const reference=weddingIdentityReference(scene,style),reason=W.sceneFailures[scene]||'第一次生成失败';try{const src=await weddingGenerateScene(c,scene,formalwear,{reference,reason,style});W.sceneImages[scene]=src;delete W.sceneFailures[scene];const key=weddingSceneKey(c,scene,formalwear,W.generationId,style);if(typeof imgPut==='function')await imgPut(key,{src,verified:W.sceneVerify[scene],createdAt:Date.now(),retried:true,referenceScene:reference&&reference.scene||''});return src;}catch(e){W.sceneImages[scene]=weddingScenes(style)[scene];W.sceneVerify[scene]={pass:false,reason:String(e&&e.weddingReason||e&&e.message||e).slice(0,160)};return W.sceneImages[scene];}}

function weddingMusicElement(style){const src=weddingBgm(style||W.session&&W.session.style);if(W.bgm&&W.bgm.getAttribute('data-wedding-src')===src)return W.bgm;if(W.bgm)weddingMusicStop();try{const a=new Audio(src);a.loop=true;a.preload='auto';a.volume=.34;a.setAttribute('data-wedding-src',src);a.setAttribute('playsinline','');a.setAttribute('webkit-playsinline','');W.bgm=a;return a;}catch(_){return null;}}
function weddingMusicPlay(reset){const a=weddingMusicElement();if(!a)return false;try{if(reset)a.currentTime=0;a.loop=true;a.volume=.34;const p=a.play();if(p&&p.catch)p.catch(()=>{});return true;}catch(_){return false;}}
function weddingMusicStop(){const a=W.bgm;if(!a)return;try{a.pause();a.currentTime=0;}catch(_){}W.bgm=null;}
async function weddingStartSimulation(cid,mid,style){if(!weddingPrivateApp())return;if(cid)W.selectedCid=cid;else if(!W.selectedCid)W.selectedCid=weddingInvitationRole()&&weddingInvitationRole().id||'';const c=getC(W.selectedCid);if(!weddingEligibleRole(c))return toast('婚礼只能与情侣空间绑定的角色进行');let m=mid&&msgs(c.id).find(x=>x&&x.id===mid&&x.type==='weddinginvite');style=weddingStyleKey(style||m&&m.style);if(!m||m.phase!=='ready'||m.supersededAt)m=weddingLatestReadyInvite(c,style);let prepared=m&&weddingState().prepared[m.preparedId],preparedId=m&&m.preparedId||'';if(!prepared&&mid){const context=weddingSceneContext(c.id,mid);if(context&&weddingStyleKey(context.prepared.style)===style){prepared=context.prepared;preparedId=context.preparedId;}}if(!prepared){const ref=weddingLatestPreparedEntry(c,style);if(ref){prepared=ref.prepared;preparedId=ref.id;}}if(!prepared){weddingRegenerate(c.id,style);return toast('还没有准备完整的'+(style==='chinese'?'中式':'现代')+'婚礼，已转入后台生成；完成后再点模拟即可直接观看');}const invite=m&&m.phase==='ready'&&!m.supersededAt?m:{id:preparedId,preparedId,eventAt:Date.now(),style,phase:'ready'};return weddingEnterPrepared(c,invite,prepared,true);}
async function weddingStart(mode,style){if(W.busy||!W.selectedCid)return;style=weddingStyleKey(style);const c=getC(W.selectedCid);if(!weddingEligibleRole(c))return toast('婚礼只能与情侣空间绑定的角色进行');const ready=weddingLatestReadyInvite(c,style);if(mode==='simulation')return weddingStartSimulation(c.id,ready&&ready.id,style);if(ready){weddingClose();return weddingOpenReadyInvite(c.id,ready.id);}return weddingRegenerate(c.id,style);}
function weddingBuildItems(s,simulation,style){style=weddingStyleKey(style);if(style==='chinese')return[{kind:'narrator',scene:'sedan',text:s.opening_narration},{kind:'role',scene:'sedan',text:s.opening_line},{kind:'choice',id:'hand',scene:'sedan',text:s.hand_prompt,choices:s.hand_choices},{kind:'narrator',scene:'silk',text:s.silk_narration},{kind:'role',scene:'silk',text:s.silk_line},{kind:'ceremony',scene:'bow',speaker:'司礼',text:'一拜天地——'},{kind:'narrator',scene:'bow',text:s.heaven_narration},{kind:'role',scene:'bow',text:s.heaven_line},{kind:'ceremony',scene:'bow',speaker:'司礼',text:'二拜高堂——'},{kind:'narrator',scene:'bow',text:s.high_narration},{kind:'role',scene:'bow',text:s.high_line},{kind:'ceremony',scene:'couple',speaker:'司礼',text:'夫妻对拜——'},{kind:'narrator',scene:'couple',text:s.couple_narration},{kind:'role',scene:'couple',text:s.couple_line},{kind:'narrator',scene:'toast',text:s.toast_narration},{kind:'role',scene:'toast',text:s.toast_line},{kind:'narrator',scene:'veil',text:s.veil_narration},{kind:'role',scene:'veil',text:s.veil_line},{kind:'narrator',scene:'veil',text:s.ending_narration},{kind:'role',scene:'veil',text:s.ending_line},{kind:'finish',scene:'veil',text:simulation?'模拟礼成，所见只留在本次预览。':'三书已定，六礼既成，你们将共同落笔婚书。',label:simulation?'模拟共书婚约':'共同签下中式婚书'}];return[{kind:'narrator',scene:'welcome',text:s.opening_narration},{kind:'role',scene:'welcome',text:s.opening_line},{kind:'action',scene:'welcome',text:'他仍正面向你伸着手，指尖停在离你很近的地方。',label:'向他走过去'},{kind:'choice',id:'hand',scene:'welcome',text:s.hand_prompt,choices:s.hand_choices},{kind:'narrator',scene:'aisle',text:s.aisle_narration},{kind:'role',scene:'aisle',text:s.aisle_line},{kind:'ceremony',scene:'aisle',speaker:'司仪',text:s.officiant_line},{kind:'choice',id:'vow',scene:'aisle',text:s.vow_prompt,choices:s.vow_choices},{kind:'narrator',scene:'vow',text:s.vow_narration},{kind:'role',scene:'vow',text:s.vow_line},{kind:'action',scene:'vow',text:'他双手合起完整的誓词纸，随后轻轻抬起你的手，目光停在你的手背上。',label:'把手背交给他'},{kind:'narrator',scene:'kiss',text:s.kiss_narration},{kind:'role',scene:'kiss',text:s.kiss_line},{kind:'action',scene:'kiss',text:'他从你的手背前直起身，婚戒正安静地躺在掌心。',label:'看向他掌心的戒指'},{kind:'choice',id:'ring',scene:'ring',text:s.ring_prompt,choices:s.ring_choices},{kind:'narrator',scene:'ring',text:s.ring_narration},{kind:'role',scene:'ring',text:s.ring_line},{kind:'narrator',scene:'embrace',text:s.blessing_narration},{kind:'ceremony',scene:'embrace',speaker:'司仪',text:s.blessing_line},{kind:'narrator',scene:'embrace',text:s.ending_narration},{kind:'role',scene:'embrace',text:s.ending_line},{kind:'finish',scene:'embrace',text:simulation?'模拟仪式到这里结束，所有内容都只停留在本次预览中。':'仪式结束了，你们的名字将一起写进今天。',label:simulation?'模拟签下婚书':'共同签下现代婚书'}];}
const weddingBuildItemsOriginal=weddingBuildItems;
weddingBuildItems=function(s,simulation,style){
  style=weddingStyleKey(style);
  if(style==='chinese')return weddingBuildItemsOriginal(s,simulation,style);
  return[
    {kind:'narrator',scene:'welcome',text:s.opening_narration},
    {kind:'role',scene:'welcome',text:s.opening_line},
    {kind:'action',scene:'welcome',text:'他仍正面向你伸着手，指尖停在离你很近的地方。',label:'向他走过去'},
    {kind:'choice',id:'hand',scene:'welcome',text:s.hand_prompt,choices:s.hand_choices},
    {kind:'narrator',scene:'aisle',text:s.aisle_narration},
    {kind:'role',scene:'aisle',text:s.aisle_line},
    {kind:'ceremony',scene:'aisle',speaker:'司仪',text:s.officiant_line},
    {kind:'choice',id:'vow',scene:'aisle',text:s.vow_prompt,choices:s.vow_choices},
    {kind:'narrator',scene:'vow',text:s.vow_narration},
    {kind:'role',scene:'vow',text:s.vow_line},
    {kind:'action',scene:'vow',text:'他双手合起完整的誓词纸，随后摊开掌心，婚戒在灯光下安静地等待着。',label:'看向他掌心的戒指'},
    {kind:'choice',id:'ring',scene:'ring',text:s.ring_prompt,choices:s.ring_choices},
    {kind:'narrator',scene:'ring',text:s.ring_narration},
    {kind:'role',scene:'ring',text:s.ring_line},
    {kind:'action',scene:'ring',text:'婚戒已经稳稳留在左手无名指上，他没有松开你的手，只把它轻轻托得更近。',label:'把戴着婚戒的手交给他'},
    {kind:'narrator',scene:'kiss',text:s.kiss_narration},
    {kind:'role',scene:'kiss',text:s.kiss_line},
    {kind:'narrator',scene:'embrace',text:s.blessing_narration},
    {kind:'ceremony',scene:'embrace',speaker:'司仪',text:s.blessing_line},
    {kind:'narrator',scene:'embrace',text:s.ending_narration},
    {kind:'role',scene:'embrace',text:s.ending_line},
    {kind:'finish',scene:'embrace',text:simulation?'模拟仪式到这里结束，所有内容都只停留在本次预览中。':'仪式结束了，你们的名字将一起写进今天。',label:simulation?'模拟签下婚书':'共同签下现代婚书'}
  ];
};
function weddingCurrent(){return W.session&&W.session.items[W.session.index];}
function weddingChoiceHTML(item){return '<div class="wedding-choice">'+item.choices.map((x,i)=>'<button onclick="event.stopPropagation();weddingChoose('+i+')">'+esc(x.text)+'</button>').join('')+'</div>';}
function weddingActionHTML(item){return '<div class="wedding-action"><button onclick="event.stopPropagation();weddingAdvance()">'+esc(item.label)+'</button></div>';}
function weddingEnsureStage(c){const root=weddingEnsureRoot();if(W.stageReady&&document.getElementById('weddingStage'))return;const chinese=W.session&&W.session.style==='chinese',opening=W.opening?' wedding-stage-opening':'';root.innerHTML='<section class="wedding-stage '+(chinese?'wedding-stage-chinese':'wedding-stage-modern')+opening+'" id="weddingStage" onclick="weddingAdvance()"><div class="wedding-art-stack"><div class="wedding-art" data-layer="0"></div><div class="wedding-art" data-layer="1"></div></div>'+weddingPetals()+'<div class="wedding-opening-veil" aria-hidden="true"></div><div class="wedding-topbar"><span class="wedding-topbar-spacer" aria-hidden="true"></span><div class="wedding-topbar-center"><small>'+(chinese?'囍 · 良 辰 吉 时':'OUR WEDDING')+'</small><b>'+esc(weddingRoleName(c))+'</b></div><span class="wedding-topbar-spacer" aria-hidden="true"></span></div><div class="wedding-dialog-host" id="weddingDialogHost"></div></section>';W.stageReady=true;W.scene='';W.activeLayer=0;W.opening=false;}
function weddingSetScene(scene){if(W.scene===scene)return;const layers=document.querySelectorAll('#weddingStage .wedding-art');if(layers.length<2)return;const scenes=weddingScenes(W.session&&W.session.style),first=weddingSceneOrder(W.session&&W.session.style)[0],next=W.scene?1-W.activeLayer:0,old=W.activeLayer,nextEl=layers[next],oldEl=layers[old],src=W.sceneImages[scene]||scenes[scene]||scenes[first];clearTimeout(W.sceneTimer);nextEl.className='wedding-art wedding-art-'+scene;nextEl.style.backgroundImage="url('"+String(src).replace(/'/g,'%27')+"')";void nextEl.offsetWidth;if(W.scene&&oldEl!==nextEl)oldEl.classList.remove('active');nextEl.classList.add('active');W.activeLayer=next;W.scene=scene;if(oldEl!==nextEl)W.sceneTimer=setTimeout(()=>{oldEl.className='wedding-art';oldEl.style.backgroundImage='';},1400);}
function weddingRenderStory(){const s=W.session,item=weddingCurrent(),c=s&&getC(s.cid);if(!s||!item||!c)return weddingClose();item.text=weddingDisplayText(item,s.style);weddingEnsureStage(c);weddingSetScene(item.scene||'welcome');clearTimeout(W.typingTimer);W.typingDone=!['role','narrator','ceremony'].includes(item.kind);const speaker=item.kind==='role'?weddingRoleName(c):item.kind==='narrator'?'旁白':item.kind==='ceremony'?(item.speaker||'司仪'):'此刻',controls=item.kind==='choice'?weddingChoiceHTML(item):['action','finish'].includes(item.kind)?weddingActionHTML(item):'<div class="wedding-next"><span>点击继续</span><i></i></div>',host=document.getElementById('weddingDialogHost');host.innerHTML='<div class="wedding-dialog wedding-dialog-'+esc(item.kind)+' '+(item.kind==='narrator'?'narrator':item.kind==='ceremony'?'ceremony':'')+'"><div class="wedding-speaker">'+esc(speaker)+'</div><div class="wedding-dialog-text" id="weddingLine">'+(['role','narrator','ceremony'].includes(item.kind)?'':esc(item.text))+'</div>'+controls+'</div>';if(host.animate)host.animate([{opacity:.68,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:260,easing:'ease-out'});if(['role','narrator','ceremony'].includes(item.kind))weddingTypeLine(item.text);}
function weddingTypeLine(text){const el=document.getElementById('weddingLine'),chars=Array.from(String(text||''));if(!el)return;let i=0;el.textContent='';W.typingDone=false;const tick=()=>{if(!el.isConnected)return;const step=i<8?1:2;i=Math.min(chars.length,i+step);el.textContent=chars.slice(0,i).join('');if(i<chars.length)W.typingTimer=setTimeout(tick,31);else W.typingDone=true;};tick();}
