  const inviteHint='七夕自动首邀一生只发一次；清空后也不会因重新打开而自动重发。你主动索要、手动生成，或你们约定的婚期到时仍可正常发送。';
  if(!await uiConfirm('清空和 '+weddingRoleName(c)+' 的全部婚礼数据？\n\n会删除：现代与中式婚礼演出、高清影集、婚书收藏、婚礼邀请与婚后消息、婚礼重要记忆、结婚日期和夫妻关系。\n不会删除：普通微信、其他记忆、单次线下约会、共同生活或其他角色资料。\n\n'+inviteHint,{danger:true}))return;
  const now=Date.now(),st=weddingState(),ids=new Set([...(Array.isArray(c._weddingMemoryIds)?c._weddingMemoryIds:[]),...st.records.filter(x=>x&&x.cid===cid).map(x=>x.id)]),list=msgs(c.id);
  for(const m of list)if(m&&(m.type==='weddinginvite'||m._weddingInviteIntro||m._weddingReady||m._weddingAfter))m.cancelledAt=now;
  list.splice(0,list.length,...list.filter(m=>!(m&&(m.type==='weddinginvite'||m._weddingInviteIntro||m._weddingReady||m._weddingAfter))));
  st.records=st.records.filter(x=>!(x&&x.cid===c.id));
  for(const id of Object.keys(st.prepared))if(st.prepared[id]&&st.prepared[id].cid===c.id)delete st.prepared[id];
  const autoSentAt=st.invitation.autoSentAt||0,autoSentDays=Object.assign({},st.invitation.autoSentDays||{});st.invitation={cid:c.id,autoSentAt,autoSentDays,qixiReset:st.invitation.qixiReset||'v997-qixi-auto-once'};
  if(st.lastCid===c.id)delete st.lastCid;
  c.summaries=Array.isArray(c.summaries)?c.summaries.filter(x=>!weddingMemorySummary(x)):[];
  c._weddingMemoryIds=[];
  const memories=typeof memoryList==='function'?memoryList(c,'main'):[],removed=memories.filter(x=>x&&typeof x==='object'&&x.weddingRecordId&&(ids.has(x.weddingRecordId)||x.weddingStyle));
  memories.splice(0,memories.length,...memories.filter(x=>!(x&&typeof x==='object'&&x.weddingRecordId&&(ids.has(x.weddingRecordId)||x.weddingStyle))));
  c._memoryMeta=c._memoryMeta||{};c._memoryMeta.main=c._memoryMeta.main||{};for(const x of removed)delete c._memoryMeta.main[memoryNorm(x)];
  if(c._weddingRelationApplied)c.relation=c._weddingRelationBefore||'';else if(String(c.relation||'')==='夫妻')c.relation='';else c.relation=String(c.relation||'').replace(/；已结为夫妻/g,'');
  delete c._weddingRelationApplied;delete c._weddingRelationBefore;
