  if(cp){cp.married=false;delete cp.relationship;delete cp.marriedAt;delete cp.marriageDate;delete cp.marriageDateManual;delete cp.marriageDateUpdatedAt;delete cp.marriageStyle;delete cp.marriageStyles;delete cp.marriageRecordId;cp.anniversaries=Array.isArray(cp.anniversaries)?cp.anniversaries.filter(x=>!(x&&x.title==='结婚纪念日')):[];}
  S.calendar=Array.isArray(S.calendar)?S.calendar.filter(x=>!(x&&x.type==='wedding'&&x.contactId===c.id)):[];
  if(W.session&&W.session.cid===c.id)weddingClose();
  W.sceneImages={};W.sceneJobs={};W.sceneVerify={};W.sceneFailures={};W.generationId='';
  save();closeModal();if(typeof render==='function')render();
