function weddingChineseNumber(n){n=Math.max(1,Math.min(31,+n||1));if(n<10)return'一二三四五六七八九'[n-1];if(n===10)return'十';if(n<20)return'十'+'一二三四五六七八九'[n-11];if(n===20)return'二十';if(n<30)return'二十'+'一二三四五六七八九'[n-21];if(n===30)return'三十';return'三十一';}
function weddingChineseCertificateDate(value){const d=value instanceof Date?value:new Date(value||Date.now()),digits='〇一二三四五六七八九',year=String(d.getFullYear()).split('').map(x=>digits[+x]||x).join('');return'公元'+year+'年'+weddingChineseNumber(d.getMonth()+1)+'月'+weddingChineseNumber(d.getDate())+'日';}
function weddingCertificateVowColumns(vow){const text=weddingClipText(weddingSafeText(vow,'愿与君白首同心，岁岁相守。',60).replace(/[“”"'。！？!?]/g,''),20),parts=[];for(let i=0;i<text.length;i+=10)parts.push(text.slice(i,i+10));return parts.slice(0,2).map(x=>'<p class="wedding-chinese-personal">'+esc(x)+'</p>').join('');}
function weddingChineseCertificateCard(bride,groom,date,vow){bride=weddingSafeText(bride,'新娘',8);groom=weddingSafeText(groom,'新郎',8);return '<div class="wedding-cert-card wedding-cert-card-chinese"><div class="wedding-chinese-cert-content"><h2><span>婚</span><span>书</span></h2><div class="wedding-chinese-vows"><p>两姓缔结良缘一堂结同心</p><p>鸾凤和鸣愿有岁月可回首</p><p>且以深情共白头</p><p>敬以情深恩爱相携</p><p>相敬如宾举案齐眉</p><p>同担风雨共度朝夕</p><p>和顺门庭孝友睦邻</p><p>珠联璧合永结同心</p>'+weddingCertificateVowColumns(vow)+'</div><div class="wedding-chinese-meta"><p class="wedding-chinese-date">'+esc(weddingChineseCertificateDate(date))+'</p><p><span>执证人</span><b>'+esc(bride)+'</b><em>署名</em></p><p><span>执证人</span><b>'+esc(groom)+'</b><em>署名</em></p></div></div></div>';}
function weddingShowCertificate(c,record,allowReplay,simulation){const d=new Date(simulation?(record.date||Date.now()):weddingDateTimestamp(weddingOfficialDay(c,record),record.date)),date=d.getFullYear()+' / '+String(d.getMonth()+1).padStart(2,'0')+' / '+String(d.getDate()).padStart(2,'0'),vow=record.vow||'愿往后的每一次欢笑与风雨，都有我在你身旁。',bride=record.brideName||W.session&&W.session.brideName||S.me&&S.me.name||'我',groom=record.groomName||W.session&&W.session.groomName||weddingRoleOriginalName(c),style=record.style==='chinese'?'chinese':'modern',note=simulation?'模拟模式：本次不会收藏婚书、写入记忆、改变关系或发送婚后消息':'',modern='<div class="wedding-cert-card"><div class="wedding-cert-content"><h2>Marriage Certificate</h2><div class="wedding-cert-divider"><i></i></div><p>On this day, <b>'+esc(date)+'</b>, we joyfully unite<br><strong>'+esc(bride)+'</strong> and <strong>'+esc(groom)+'</strong> in marriage.</p><p>Together, we choose each other as life partners.</p><div class="wedding-cert-divider"><i></i></div><p>We promise to love and respect one another,<br>to listen with patience, forgive with grace,<br>and stand together through every season of life.</p><p>We will celebrate each other\'s dreams,<br>share both joy and sorrow,<br>and make a home wherever we are together.</p><div class="wedding-cert-divider"><i></i></div><p>With family and friends as witnesses,<br>we affirm this bond with love and gratitude.</p><p class="wedding-cert-vow">'+esc(vow)+'</p><div class="wedding-cert-ornament"><i></i></div><div class="wedding-cert-signatures"><span><i></i><small>Signature</small></span><span><i></i><small>Signature</small></span></div><div class="wedding-cert-bottom-names"><span>'+esc(bride)+'</span><i>&amp;</i><span>'+esc(groom)+'</span></div></div></div>',card=style==='chinese'?weddingChineseCertificateCard(bride,groom,d,vow):modern;W.view='certificate';weddingMount('<section class="wedding-certificate wedding-certificate-'+style+' '+(simulation?'wedding-certificate-simulation':'')+'">'+weddingCertificatePetals()+'<button class="wedding-icon-btn wedding-cert-close" onclick="weddingClose()" aria-label="退出">×</button>'+(simulation?'<div class="wedding-simulation-badge">SIMULATION · 不保存</div>':'')+card+(note?'<div class="wedding-after-note">'+esc(note)+'</div>':'')+'</section>');requestAnimationFrame(()=>{if(style==='modern'){weddingFitCertificateTitle();setTimeout(weddingFitCertificateTitle,180);setTimeout(weddingFitCertificateTitle,500);}});}
function weddingOpenCertificateRecord(cid,recordId){const c=getC(cid),record=weddingState().records.find(x=>x&&x.id===recordId&&x.cid===cid);if(!c||!record)return;W.session=null;weddingMusicStop();weddingShowCertificate(c,record,false);}
function weddingFinish(){const s=W.session,c=s&&getC(s.cid);if(!s||!weddingEligibleRole(c))return weddingClose();const style=weddingStyleKey(s.style);if(s.simulation){s.saved=true;return weddingShowCertificate(c,{id:'simulation',cid:c.id,style,date:Date.now(),choices:s.choices,vow:s.script.certificate_vow,formalwear:s.formalwear,generated:s.generated,brideName:s.brideName,groomName:s.groomName},true,true);}const st=weddingState(),ceremonyAt=Number.isFinite(+s.ceremonyAt)?+s.ceremonyAt:Date.now();let record=s.recordId&&st.records.find(x=>x&&x.id===s.recordId);if(!s.saved){record=st.records.find(x=>x&&x.cid===c.id&&(x.style||'modern')===style)||{id:'wed_'+style+'_'+weddingHash(c.id),cid:c.id,style,createdAt:Date.now()};Object.assign(record,{style,date:record.date||ceremonyAt,updatedAt:Date.now(),choices:s.choices,vow:s.script.certificate_vow,formalwear:s.formalwear,generated:s.generated,brideName:s.brideName,groomName:s.groomName,styleLabel:weddingStyleName(style)});st.records=st.records.filter(x=>x&&x!==record&&(x.cid!==c.id||(x.style||'modern')!==style));st.records.unshift(record);st.records=st.records.slice(0,12);weddingMarkMarried(c,record);const memory=weddingSaveMemory(c,s,record),runRecord={id:'wedrun_'+Date.now(),cid:c.id,style,date:ceremonyAt,certificateId:record.id};s.saved=true;s.recordId=record.id;save();setTimeout(()=>weddingAfterMessage(c,s,runRecord,memory),900);}else if(record)weddingMarkMarried(c,record);weddingShowCertificate(c,record||{style,date:ceremonyAt,vow:s.script.certificate_vow,brideName:s.brideName,groomName:s.groomName},true,false);}
